import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let requestUri = request["path"] as String
        if (!is_start_with(requestUri)) {
            return false
        }
        let jwtUser = get_jwt_user(request)
        if (jwtUser is None<HashMap<String, Any>>) {
            return false
        }
        let user = jwtUser.getOrThrow()
        set_current_user_info_and_log(user)
        return true
    }

    public func is_start_with(request_uri: String): Bool {
        request_uri.starts_with("/api") || request_uri.starts_with("/login")
    }

