        let currentDate = DateTime.now().format("yyyy-MM-dd")
        if (jwtToken.ends_with(currentDate)) {
            Some<HashMap<String, Any>>(auth["user"] as HashMap<String, Any>)
        } else {
            None<HashMap<String, Any>>
        }
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        println("User access: ${user["name"]}")
    }
