import std.time.DateTime

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let requestUri = request["path"] ?? ""
        if (is_start_with(requestUri)) {
            let jwtUser = get_jwt_user(request)
            if (jwtUser is None) {
                return false
            }
            set_current_user_info_and_log(jwtUser.getOrThrow())
            return true
        }
        return false
    }

    public func is_start_with(request_uri: String): Bool {
        request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request["headers"] as? HashMap<String, Any>
        if (headers is None) {
            return None<HashMap<String, Any>>
        }
        let authorization = headers.getOrThrow()["Authorization"] as? HashMap<String, Any>
        if (authorization is None) {
            return None<HashMap<String, Any>>
        }
        let token = authorization.getOrThrow()["jwt"] as? String
        let user = authorization.getOrThrow()["user"] as? HashMap<String, Any>
        if (token is None || user is None) {
            return None<HashMap<String, Any>>
        }
        let now = DateTime.now().format("yyyy-MM-dd")
        if (token.getOrThrow().endsWith(now)) {
            return Some<HashMap<String, Any>>(user.getOrThrow())
        }
        return None<HashMap<String, Any>>
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        println("User ${user["name"]} accessed at ${DateTime.now()}")
    }
}

