        let path: Option<Any> = request.get("path")
        let method: Option<Any> = request.get("method")

        if (path.isNone() || method.isNone()) {
            return false
        }

        let path_str: String = path.getOrThrow() as String
        let method_str: String = method.getOrThrow() as String

        if (method_str == "OPTIONS") {
            return true
        }

        if (!is_start_with(path_str)) {
            return false
        }

        let user: Option<HashMap<String, Any>> = get_jwt_user(request)
        if (user.isNone()) {
            return false
        }

        set_current_user_info_and_log(user.getOrThrow())
        return true
    }

    public func is_start_with(request_uri: String): Bool {
        request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers: Option<Any> = request.get("headers")
        if (headers.isNone()) {
            return None<HashMap<String, Any>>()
        }

        let headers_map = headers.getOrThrow() as HashMap<String, Any>
        let auth: Option<Any> = headers_map.get("Authorization")
        if (auth.isNone()) {
            return None<HashMap<String, Any>>()
        }

        let auth_map = auth.getOrThrow() as HashMap<String, Any>
        let jwt: Option<Any> = auth_map.get("jwt")
        let user: Option<Any> = auth_map.get("user")

        if (jwt.isNone() || user.isNone()) {
            return None<HashMap<String, Any>>()
        }

        let jwt_str = jwt.getOrThrow() as String
        let date_str = DateTime.now().format("yyyy-MM-dd")

        if (jwt_str != (user.getOrThrow() as HashMap<String, Any>).get("name").getOrThrow() as String + date_str) {
            return None<HashMap<String, Any>>()
        }

        Some<HashMap<String, Any>>(user.getOrThrow() as HashMap<String, Any>)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name: Option<Any> = user.get("name")
        let address: Option<Any> = user.get("address")

        if (name.isSome() && address.isSome()) {
            println("User ${name.getOrThrow() as String} accessed from ${address.getOrThrow() as String}")
        }
    }
}

