import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let tokens = command_string.split(" ")
        let args = ArrayList<String>()

        // Skip the first token (program name)
        for (i in 1..tokens.size) {
            args.add(tokens[i])
        }

        var i = 0
        while (i < args.size) {
            let token = args[i]
            if (token.startsWith("--")) {
                // Long option (--option or --key=value)
                let parts = token.split("=")
                if (parts.size == 2) {
                    // --key=value format
                    let key = parts[0].substring(2)
                    arguments.add(key, convert_type(key, parts[1]))
                } else {
                    // --option format
                    let key = token.substring(2)
                    arguments.add(key, true)
                }
                i += 1
            } else if (token.startsWith("-")) {
                // Short option (-option or -key value)
                let key = token.substring(1)
                if (i + 1 < args.size && !args[i + 1].startsWith("-")) {
                    // -key value format
                    arguments.add(key, convert_type(key, args[i + 1]))
                    i += 2
                } else {
                    // -option format
                    arguments.add(key, true)
                    i += 1
                }
            } else {
                i += 1
            }
        }

        // Check required arguments
        let missing = HashSet<String>()
        for (req in required) {
            if (!arguments.contains(req)) {
                missing.add(req)
            }
        }

        if (missing.size > 0) {
            return (false, Some(missing))
        }
        return (true, None<HashSet<String>>())
    }

    public func get_argument(key: String): Any {
        match (arguments.get(key)) {
            case Some(value) => return value
            case None => return None<Any>()
        }
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if (required) {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        match (types.get(arg)) {
            case Some(type_info) => {
                if (type_info == TypeInfo.of<Int64>()) {
                    return value.toInt64()
                } else if (type_info == TypeInfo.of<Float64>()) {
                    return value.toFloat64()
                } else if (type_info == TypeInfo.of<Bool>()) {
                    return value.toLowerCase() == "true"
                }
                return value
            }
            case None => return value
        }
    }
}

