class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let tokens = command_string.split(" ")
        let mutable_args = HashSet<String>(required)

        for i in 0..tokens.size {
            let token = tokens[i]
            if (token.startsWith("--")) {
                let parts = token.split("=")
                if (parts.size == 2) {
                    let arg = parts[0][2..]
                    let value = convert_type(arg, parts[1])
                    arguments.add(arg, value)
                    mutable_args.remove(arg)
                } else {
                    arguments.add(token[2..], true)
                }
            } else if (token.startsWith("-")) {
                if (i + 1 < tokens.size && !tokens[i+1].startsWith("-")) {
                    let arg = token[1..]
                    let value = convert_type(arg, tokens[i+1])
                    arguments.add(arg, value)
                    mutable_args.remove(arg)
                } else {
                    arguments.add(token[1..], true)
                }
            }
        }

        if (mutable_args.size > 0) {
            return (false, Some(mutable_args))
        }
        return (true, None)
    }

    public func get_argument(key: String): Any {
        if (arguments.contains(key)) {
            return arguments.get(key)
        }
        return None
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if (required) {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        if (types.contains(arg)) {
            let type_info = types.get(arg)
            if (type_info == TypeInfo.of<Int64>()) {
                return value.toInt64()
            } else if (type_info == TypeInfo.of<Float64>()) {
                return value.toFloat64()
            } else if (type_info == TypeInfo.of<Bool>()) {
                return value == "true"
            }
        }
        return value
    }
}

