                    let value = part.substring(equalPos + 1)
                    let converted = convert_type(key, value)
                    arguments.add(key, converted)
                    i = i + 1
                } else {
                    let key = part.substring(2)
                    arguments.add(key, true)
                    i = i + 1
                }
            } else if (part.startsWith("-")) {
                let key = part.substring(1)
                if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                    let value = parts[i + 1]
                    let converted = convert_type(key, value)
                    arguments.add(key, converted)
                    i = i + 2
                } else {
                    arguments.add(key, true)
                    i = i + 1
                }
            } else {
                i = i + 1
            }
        }

        var missing = HashSet<String>()
        for (req in required) {
            if (!arguments.contains(req)) {
                missing.add(req)
            }
        }

        if (missing.size > 0) {
