            let type_info = types.get(arg).getOrThrow()
            if (type_info == TypeInfo.of<Int64>()) {
                return Int64.parse(value)
            } else if (type_info == TypeInfo.of<Float64>()) {
                return Float64.parse(value)
            } else if (type_info == TypeInfo.of<Bool>()) {
                return value == "true"
            }
        }
