    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ")
        var i = 0
        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                let kv = part[2..].split("=")
                if (kv.size == 2) {
                    let key = kv[0]
                    let value = convert_type(key, kv[1])
                    arguments.add(key, value)
                } else {
                    arguments.add(kv[0], true)
                }
            } else if (part.startsWith("-")) {
                let key = part[1..]
                if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                    let value = convert_type(key, parts[i + 1])
                    arguments.add(key, value)
                    i += 1
                } else {
                    arguments.add(key, true)
                }
            }
            i += 1
        }

        let missing = HashSet<String>()
        for req in required {
            if (!arguments.contains(req)) {
                missing.add(req)
            }
        }

        if (missing.size > 0) {
            return (false, Some<HashSet<String>>(missing))
        }
        return (true, None<HashSet<String>>())
    }

    public func get_argument(key: String): Any {
        return arguments.get(key) ?? None<Any>()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if (required) {
            this.required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        let typeOpt = types.get(arg)
        if (typeOpt.isNone()) {
            return value
        }
        let typeInfo = typeOpt.getOrThrow()
        if (typeInfo == TypeInfo.of<Int64>()) {
            return value.toInt64()
        } else if (typeInfo == TypeInfo.of<Float64>()) {
            return value.toFloat64()
        } else if (typeInfo == TypeInfo.of<Bool>()) {
            return value.toLowerCase() == "true"
        }
        return value
    }
}

