class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ")
        let mut i = 0

        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                // Handle --arg=value format
                let argValue = part.split("=")
                let argName = argValue[0].substring(2)
                if (argValue.size > 1) {
                    let value = argValue[1]
                    arguments.add(argName, convert_type(argName, value))
                } else {
                    arguments.add(argName, true)
                }
            } else if (part.startsWith("-")) {
                // Handle -arg value format
                let argName = part.substring(1)
                if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                    let value = parts[i + 1]
                    arguments.add(argName, convert_type(argName, value))
                    i += 1
                } else {
                    arguments.add(argName, true)
                }
            }
            i += 1
        }

        // Check required arguments
        let missing = HashSet<String>()
        for (req in required) {
            if (!arguments.contains(req)) {
                missing.add(req)
            }
        }

        if (missing.size > 0) {
            return (false, Some(missing))
        }
        return (true, None)
    }

    public func get_argument(key: String): Any {
        if (arguments.contains(key)) {
            return arguments.get(key).getOrThrow()
        }
        return None<Any>()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if (required) {
            required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        if (!types.contains(arg)) {
            return value
        }

        let typeInfo = types.get(arg).getOrThrow()

        match (typeInfo.typeName) {
            case "Int64" => return Int64.fromString(value).getOrThrow()
            case "Float64" => return Float64.fromString(value).getOrThrow()
            case "Bool" => return value.lower() == "true"
            case _ => return value
        }
    }
}

import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let k = m ?? n
        if (n < k) {
            return 0
        }
        return factorial(n) / factorial(n - k)
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (i in 1..n+1) {
            total += factorial(n) / factorial(n - i)
        }
        return total
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let k = m ?? datas.size
        let result = ArrayList<ArrayList<Int64>>([])
        if (k <= datas.size) {
            select_permutations(ArrayList<Int64>([]), ArrayList<Int64>(datas), k, result)
        }
        return result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>([])
        for (i in 1..datas.size+1) {
            select_permutations(ArrayList<Int64>([]), ArrayList<Int64>(datas), i, result)
        }
        return result
    }

    public static func factorial(n: Int64): Int64 {
        if (n <= 1) {
            return 1
        }
        return n * factorial(n - 1)
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if (prefix.size == m) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m, result)
        }
    }
}

