import std.collection.*

class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let n1 = num1.toRuneArray()
        let n2 = num2.toRuneArray()
        var res = ArrayList<Rune>()
        var i = n1.size - 1
        var j = n2.size - 1
        var carry = 0

        while (i >= 0 || j >= 0 || carry > 0) {
            let d1 = if (i >= 0) { n1[i].toInt() - r'0'.toInt() } else { 0 }
            let d2 = if (j >= 0) { n2[j].toInt() - r'0'.toInt() } else { 0 }
            let sum = d1 + d2 + carry
            res.add(r'0' + sum % 10, at: 0)
            carry = sum / 10
            i = i - 1
            j = j - 1
        }

        return String(res.toArray())
    }

    public static func subtract(num1: String, num2: String): String {
        let cmp = compareAbs(num1, num2)
        if (cmp == 0) {
            return "0"
        }

        let n1 = if (cmp > 0) { num1.toRuneArray() } else { num2.toRuneArray() }
        let n2 = if (cmp > 0) { num2.toRuneArray() } else { num1.toRuneArray() }
        var res = ArrayList<Rune>()
        var i = n1.size - 1
        var j = n2.size - 1
        var borrow = 0

        while (i >= 0 || j >= 0) {
            let d1 = n1[i].toInt() - r'0'.toInt()
            let d2 = if (j >= 0) { n2[j].toInt() - r'0'.toInt() } else { 0 }
            let diff = d1 - d2 - borrow
            if (diff < 0) {
                res.add(r'0' + diff + 10, at: 0)
                borrow = 1
            } else {
                res.add(r'0' + diff, at: 0)
                borrow = 0
            }
            i = i - 1
            j = j - 1
        }

        // Remove leading zeros
        while (res.size > 1 && res[0] == r'0') {
            res.remove(at: 0)
        }

        return (if (cmp > 0) { "" } else { "-" }) + String(res.toArray())
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let n1 = num1.toRuneArray()
        let n2 = num2.toRuneArray()
        var res = ArrayList<Int64>([]).fill(0, n1.size + n2.size)

        for (i in 0..n1.size:1) {
            for (j in 0..n2.size:1) {
                let d1 = n1[i].toInt() - r'0'.toInt()
                let d2 = n2[j].toInt() - r'0'.toInt()
                res[i + j + 1] = res[i + j + 1] + d1 * d2
            }
        }

        var carry = 0
        for (k in (0..res.size:1).descending()) {
            let sum = res[k] + carry
            res[k] = sum % 10
            carry = sum / 10
        }

        // Remove leading zeros
        while (res.size > 1 && res[0] == 0) {
            res.remove(at: 0)
        }

        return String(res.toArray().map({x: Int64 => r'0' + x}))
    }

    private static func compareAbs(num1: String, num2: String): Int64 {
        if (num1.size > num2.size) {
            return 1
        } else if (num1.size < num2.size) {
            return -1
        } else {
            for (i in 0..num1.size:1) {
                let c1 = num1[i]
                let c2 = num2[i]
                if (c1 > c2) {
                    return 1
                } else if (c1 < c2) {
                    return -1
                }
            }
            return 0
        }
    }
}

