        let reversed2 = reverseString(paddedSmaller).toRuneArray()

        var result = ArrayList<Rune>()
        var borrow = 0

        for (i in 0..maxLength) {
            let digit1 = reversed1[i].toString().parseInt64() ?? 0
            let digit2 = reversed2[i].toString().parseInt64() ?? 0

            var difference = digit1 - digit2 - borrow

            if (difference < 0) {
                difference += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.add(r'${difference}', at: 0)
        }

        // Remove leading zeros
        while (result.size > 1 && result[0] == r'0') {
            result.remove(at: 0)
        }

        let resultStr = String.fromRuneArray(result)
        return if (isNegative) { "-${resultStr}" } else { resultStr }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let len1 = num1.size
        let len2 = num2.size
        let resultLength = len1 + len2
        var result = ArrayList<Int64>(new Array<Int64>(resultLength) { 0 })

        let reversed1 = reverseString(num1).toRuneArray()
        let reversed2 = reverseString(num2).toRuneArray()

        for (i in 0..len1) {
            for (j in 0..len2) {
                let digit1 = reversed1[i].toString().parseInt64() ?? 0
                let digit2 = reversed2[j].toString().parseInt64() ?? 0

                let product = digit1 * digit2
                result[i + j] += product
                result[i + j + 1] += result[i + j] / 10
                result[i + j] = result[i + j] % 10
            }
        }

        // Remove leading zeros
        while (result.size > 1 && result[result.size - 1] == 0) {
            result.remove(at: result.size - 1)
        }

        // Convert to string
        let reversedResult = result.reverse()
        var resultStr = ""
        for (i in 0..reversedResult.size) {
            resultStr += reversedResult[i].toString()
        }

        return resultStr
    }
}

