class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'
        */
        let a = num1.reversed()
        let b = num2.reversed()
        var result = ArrayList<Rune>([])
        var carry = 0
        let maxLength = if (a.size > b.size) { a.size } else { b.size }

        for (i in 0..maxLength) {
            let digit1 = if (i < a.size) { a[i].toString().toInt64() ?? 0 } else { 0 }
            let digit2 = if (i < b.size) { b[i].toString().toInt64() ?? 0 } else { 0 }
            let sum = digit1 + digit2 + carry
            carry = sum / 10
            result.add(r'0' + (sum % 10).toRune(), at: 0)
        }

        if (carry > 0) {
            result.add(r'0' + carry.toRune(), at: 0)
        }

        return result.join("")
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'
        */
        let isNegative = if (num1.size < num2.size || (num1.size == num2.size && num1 < num2)) { true } else { false }
        let a = if (isNegative) { num2.reversed() } else { num1.reversed() }
        let b = if (isNegative) { num1.reversed() } else { num2.reversed() }
        var result = ArrayList<Rune>([])
        var borrow = 0

        for (i in 0..a.size) {
            let digit1 = a[i].toString().toInt64() ?? 0
            let digit2 = if (i < b.size) { b[i].toString().toInt64() ?? 0 } else { 0 }
            var diff = digit1 - digit2 - borrow
            borrow = if (diff < 0) { 1 } else { 0 }
            diff = if (diff < 0) { diff + 10 } else { diff }
            result.add(r'0' + diff.toRune(), at: 0)
        }

        while (result.size > 1 && result[0] == r'0') {
            result.remove(at: 0)
        }

        if (isNegative) {
            result.add(r'-', at: 0)
        }

        return result.join("")
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'
        */
        let a = num1.reversed()
        let b = num2.reversed()
        var products = ArrayList<ArrayList<Int64>>([])

        for (i in 0..b.size) {
            let digit2 = b[i].toString().toInt64() ?? 0
            var product = ArrayList<Int64>([])
            var carry = 0

            for (j in 0..a.size) {
                let digit1 = a[j].toString().toInt64() ?? 0
                let temp = digit1 * digit2 + carry
                carry = temp / 10
                product.add(temp % 10)
            }

            if (carry > 0) {
                product.add(carry)
            }

            for (k in 0..i) {
                product.add(0, at: 0)
            }

            products.add(product)
        }

        var sum = "0"
        for (p in products) {
            let pStr = p.map({x => x.toString()}).join("")
            sum = add(sum, pStr)
        }

        return sum
    }
}

