        result.add("Zeroes", zeros / length)
        result.add("Ones", ones / length)
        result.add("Bit length", length)
        return result
    }

    public func convert_to_ascii(): String {
        let chunks = this.split_into_chunks(8)
        var result = ArrayList<Rune>([])

        for (chunk in chunks) {
            let decimal = chunk.toInt(radix: 2).getOrThrow()
            result.add(decimal.toRune())
        }

        return result.toArray().map({c: Rune => c.toString()}).join("")
    }

    public func convert_to_utf8(): String {
        // UTF-8 conversion follows same byte-level approach as ASCII for these simple cases
        this.convert_to_ascii()
    }

    private func split_into_chunks(size: Int64): ArrayList<String> {
        var chunks = ArrayList<String>([])
        var index = 0
        let str = this.binary_string

        while (index < str.size) {
            let end = if (index + size < str.size) { index + size } else { str.size }
            chunks.add(str.substring(index, end))
            index += size
        }

        return chunks
    }
}

