class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        for (i in (0..patLen).rev()) {
            if (pattern[i] == char) {
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        let endPos = min(currentPos + patLen, textLen)
        var mismatchPos: Int64 = -1
        for (i in currentPos..endPos) {
            if (text[i] != pattern[i - currentPos]) {
                mismatchPos = i - currentPos
                break
            }
        }
        return mismatchPos
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let occurrences = ArrayList<Int64>()
        var currentPos: Int64 = 0

        while (currentPos <= textLen - patLen) {
            let mismatchPos = mismatch_in_text(currentPos: currentPos)
            if (mismatchPos == -1) {
                occurrences.add(currentPos)
                currentPos += 1
            } else {
                let badChar = text[currentPos + mismatchPos]
                let indexInPattern = match_in_pattern(char: badChar)
                currentPos += max(1, mismatchPos - indexInPattern)
            }
        }
        return occurrences
    }
}

