        var mismatchPos: Int64 = -1
        for (i in (this.patLen - 1)..0:-1) {
            if (currentPos + i >= this.textLen) {
                continue
            }
            if (this.pattern.toRuneArray()[i] != this.text.toRuneArray()[currentPos + i]) {
                mismatchPos = i
