        while (s <= this.textLen - this.patLen) {
            let mismatchPos = this.mismatch_in_text(s)
            if (mismatchPos == -1) {
                results.add(s)
                s += 1
            } else {
                let char = this.text.toRuneArray()[s + mismatchPos]
                let rightmostPos = this.match_in_pattern(char.to_string())
                s += max(1, mismatchPos - rightmostPos)
            }
        }
        return results
    }
