        let operand_stack = ArrayList<Float64>([])
        let operator_stack = ArrayList<String>([])

        var i = 0
        while (i < expression.toRuneArray().size) {
            let c = expression.toRuneArray()[i]
            if (c == r' ') {
                i += 1
                continue
            }

            if (c.isDigit()) {
                var num_str = ""
                while (i < expression.toRuneArray().size && expression.toRuneArray()[i].isDigit()) {
                    num_str += expression.toRuneArray()[i].toString()
                    i += 1
                }
                operand_stack.add(num_str.parseFloat64().getOrThrow())
                continue
            }

            if (c == r'(') {
                operator_stack.add(c.toString())
                i += 1
                continue
            }

            if (c == r')') {
                while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                    let (new_op_stack, new_oper_stack) = apply_operator(operand_stack, operator_stack)
                    operand_stack = new_op_stack
                    operator_stack = new_oper_stack
                }
                operator_stack.remove(at: operator_stack.size - 1)
                i += 1
                continue
            }

            while (operator_stack.size > 0 && precedence(operator_stack[operator_stack.size - 1]) >= precedence(c.toString())) {
                let (new_op_stack, new_oper_stack) = apply_operator(operand_stack, operator_stack)
                operand_stack = new_op_stack
                operator_stack = new_oper_stack
            }
            operator_stack.add(c.toString())
            i += 1
        }

        while (operator_stack.size > 0) {
            let (new_op_stack, new_oper_stack) = apply_operator(operand_stack, operator_stack)
            operand_stack = new_op_stack
            operator_stack = new_oper_stack
        }

        if (operand_stack.size == 1) {
            return Some<Float64>(operand_stack[0])
        } else {
            return None<Float64>()
        }
    }

    public func precedence(op: String): Int64 {
        match (op) {
            case "+" => 1
            case "-" => 1
            case "*" => 2
            case "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
