import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {
    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
        this.date = date
        this.start_time = start_time
        this.end_time = end_time
        this.description = description
    }

    public override operator func != (that: Event): Bool {
        return this.date != that.date || this.start_time != that.start_time || this.end_time != that.end_time || this.description != that.description
    }

    public override operator func == (that: Event): Bool {
        return this.date == that.date && this.start_time == that.start_time && this.end_time == that.end_time && this.description == that.description
    }
}

class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        let index = this.events.indexOf(event)
        if (index != -1) {
            this.events.remove(at: index)
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (event in this.events) {
            if (event.date == date) {
                result.add(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in this.events) {
            if (!(end_time <= event.start_time || start_time >= event.end_time)) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let slots = ArrayList<(DateTime, DateTime)>()
        let day_start = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let day_end = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth+1, hour: 0, minute: 0)

        let daily_events = this.get_events(date)
        if (daily_events.size == 0) {
            slots.add((day_start, day_end))
            return slots
        }

        // Sort events by start time
        let lessThan = {l: Event, r: Event => l.start_time < r.start_time}
        sort(daily_events, lessThan: lessThan)

        // Check before first event
        if (day_start < daily_events[0].start_time) {
            slots.add((day_start, daily_events[0].start_time))
        }

        // Check between events
        for (i in 0..daily_events.size-1) {
            let current_end = daily_events[i].end_time
            let next_start = daily_events[i+1].start_time
            if (current_end < next_start) {
                slots.add((current_end, next_start))
            }
        }

        // Check after last event
        let last_event = daily_events[daily_events.size-1]
        if (last_event.end_time < day_end) {
            slots.add((last_event.end_time, day_end))
        }

        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let filtered = ArrayList<Event>()
        for (event in this.events) {
            if (event.start_time > now) {
                filtered.add(event)
            }
        }

        let lessThan = {l: Event, r: Event => l.start_time < r.start_time}
        sort(filtered, lessThan: lessThan)

        let result = ArrayList<Event>()
        let count = min(num_events, filtered.size)
        for (i in 0..count) {
            result.add(filtered[i])
        }
        return result
    }
}

