    }
}

class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        let index = this.events.findIndex({e: Event => e == event})
        if (index != -1) {
            this.events.remove(at: index)
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (event in this.events) {
            if (event.date == date) {
                result.add(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in this.events) {
            if (!(end_time <= event.start_time || start_time >= event.end_time)) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let slots = ArrayList<(DateTime, DateTime)>()
        let events_on_date = ArrayList<Event>()

        for (event in this.events) {
            if (event.date == date) {
                events_on_date.add(event)
            }
        }

        if (events_on_date.size == 0) {
            slots.add((date.startOfDay(), date.endOfDay()))
            return slots
        }

        events_on_date.sort({a: Event, b: Event => a.start_time < b.start_time})

        let first_start = events_on_date[0].start_time
        if (date.startOfDay() < first_start) {
            slots.add((date.startOfDay(), first_start))
        }

        for (i in 0..events_on_date.size-1) {
            let current_end = events_on_date[i].end_time
            let next_start = events_on_date[i+1].start_time
            if (current_end < next_start) {
                slots.add((current_end, next_start))
            }
        }

        let last_end = events_on_date[events_on_date.size-1].end_time
        if (last_end < date.endOfDay()) {
            slots.add((last_end, date.endOfDay()))
        }

        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()

        for (event in this.events) {
            if (event.start_time >= now) {
                upcoming.add(event)
            }
        }

        upcoming.sort({a: Event, b: Event => a.start_time < b.start_time})

        if (upcoming.size > num_events) {
            upcoming.removeRange(from: num_events, to: upcoming.size)
        }

        return upcoming
    }
}

