    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        let content = file_name.readFileToString()
        if (content.size == 0) {
            return (title, data)
        }

        let lines = content.split("\n")
        if (lines.size == 0) {
            return (title, data)
        }

        // Read title
        let first_line = lines[0]
        title.addAll(first_line.split(","))

        // Read data
        for (i in 1..lines.size:1) {
            let line = lines[i]
            if (line.size == 0) {
                continue
            }
            let row = ArrayList<String>(line.split(","))
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let result = ArrayList<String>()
        for (row in data) {
            result.add(row.join(","))
        }

        try {
            file_name.writeStringToFile(result.join("\n"))
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, original_data) = read_csv(save_file_name)

        if (N < 0 || N >= title.size) {
            return 0
        }

        let processed_data = ArrayList<ArrayList<String>>()
        for (row in original_data) {
            if (N >= row.size) {
                continue
            }
            let new_row = ArrayList<String>([row[N].uppercase()])
            processed_data.add(new_row)
        }

        let output_name = "${save_file_name}_process.csv"
        let output_data = ArrayList<ArrayList<String>>()
        output_data.add(title)
        output_data.addAll(processed_data)

        return write_csv(output_data, output_name)
    }
