        for (i in 1..lines.size) {
            let line = lines[i]
            let columns = line.split(",")
            let row = ArrayList<String>()
            for (column in columns) {
                row.add(column.trim())
            }
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File(file_name)
        let writer = file.writer()

        for (row in data) {
            let line = row.join(",")
            writer.write(line + "\n")
        }

        writer.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if (title.size == 0 || N < 0 || N >= title.size) {
            return 0
        }

        let processed_data = ArrayList<ArrayList<String>>()
        processed_data.add(title)

        let new_rows = ArrayList<ArrayList<String>>()
        for (row in data) {
            let new_row = ArrayList<String>()
            if (row.size > N) {
                new_row.add(row[N].toUpper())
            }
            new_rows.add(new_row)
        }

        processed_data.addAll(new_rows)

        let new_file_name = save_file_name.replace(".csv", "_process.csv")
        return write_csv(processed_data, new_file_name)
    }
}

import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        let content = readFile(file_name)
        let lines = content.split("\n")

        if (lines.size > 0) {
            let first_line = lines[0]
            for (item in first_line.split(",")) {
                title.add(item.trim())
            }
        }

        if (lines.size > 1) {
            for (i in 1..lines.size) {
                let current_line = lines[i]
                if (current_line.trim().size == 0) {
                    continue
                }
                let row = ArrayList<String>()
                for (item in current_line.split(",")) {
                    row.add(item.trim())
                }
                data.add(row)
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = open(file_name, "w")
            for (row in data) {
                let line = row.join(",")
                file.write(line + "\n")
            }
            file.close()
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, original_data) = read_csv(save_file_name)
        let processed_data = ArrayList<ArrayList<String>>()

        let processed_title = ArrayList<String>(title)
        processed_data.add(processed_title)

        for (row in original_data) {
            if (N >= 0 && N < row.size) {
                let new_row = ArrayList<String>()
                new_row.add(row[N].toUpperCase())
                processed_data.add(new_row)
            }
        }

        let new_file_name = save_file_name.replace(".csv", "") + "_process.csv"
        return write_csv(processed_data, new_file_name)
    }
}

