import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        let sum = data.reduce(0, {acc: Int64, x: Int64 => acc + x})
        let mean = sum.toFloat64() / data.size.toFloat64()
        return round(mean * 100) / 100
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        let size = sorted.size
        if (size % 2 == 1) {
            return sorted[(size - 1) / 2].toFloat64()
        } else {
            let mid1 = sorted[size / 2 - 1].toFloat64()
            let mid2 = sorted[size / 2].toFloat64()
            return round(((mid1 + mid2) / 2) * 100) / 100
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (num in data) {
            freq[num] = (freq[num] ?? 0) + 1
        }

        let maxFreq = freq.values().reduce(0, {acc: Int64, x: Int64 => if (x > acc) { x } else { acc }})
        let modes = ArrayList<Int64>()
        for ((num, count) in freq) {
            if (count == maxFreq) {
                modes.add(num)
            }
        }

        sort(modes)
        return modes
    }
}

