class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        var sum: Int64 = 0
        for (i in 0..data.size) {
            sum += data[i]
        }
        return round((sum.toFloat64() / data.size.toFloat64()) * 100) / 100
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = ArrayList<Int64>(data)
        sort(sorted_data)
        if (sorted_data.size % 2 == 1) {
            return sorted_data[sorted_data.size / 2].toFloat64()
        } else {
            let mid = sorted_data.size / 2
            return round(((sorted_data[mid - 1].toFloat64() + sorted_data[mid].toFloat64()) / 2) * 100) / 100
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        var max_count: Int64 = 0
        let result = ArrayList<Int64>()

        for (i in 0..data.size) {
            let num = data[i]
            let count = freq[num] ?? 0 + 1
            freq.add(num, count)
            if (count > max_count) {
                max_count = count
            }
        }

        for ((num, count) in freq) {
            if (count == max_count) {
                result.add(num)
            }
        }

        return result
    }
}

