class DataStatistics {

    /*
    This is a class for performing data statistics, supporting to calculate the mean, median, and mode of a given data set.
    */

    public func mean(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        let sum = { 
            var s: Int64 = 0
            for (i in 0..data.size) {
                s += data[i]
            }
            s
        }()
        let avg = (sum as Float64) / (data.size as Float64)
        return round(avg * 100) / 100
    }

    public func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        let sorted = data.clone()
        sort(sorted)
        if (sorted.size % 2 == 1) {
            return sorted[sorted.size / 2] as Float64
        } else {
            let mid = sorted.size / 2
            return round(((sorted[mid-1] + sorted[mid]) as Float64) / 2 * 100) / 100
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let frequencyMap = HashMap<Int64, Int64>()
        var maxFrequency: Int64 = 0

        for (i in 0..data.size) {
            let num = data[i]
            let count = frequencyMap.get(num) ?? 0
            frequencyMap.add(num, count + 1)
            if (count + 1 > maxFrequency) {
                maxFrequency = count + 1
            }
        }

        let modes = ArrayList<Int64>()
        for (entry in frequencyMap) {
            if (entry.value == maxFrequency) {
                modes.add(entry.key)
            }
        }

        sort(modes)
        return modes
    }
}

