class DataStatistics2 {
    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        this.data = data
    }

    public func get_sum(): Float64 {
        var sum = 0.0
        for (i in 0..this.data.size) {
            sum += this.data[i]
        }
        return sum
    }

    public func get_min(): Float64 {
        var min = this.data[0]
        for (i in 1..this.data.size) {
            if (this.data[i] < min) {
                min = this.data[i]
            }
        }
        return min
    }

    public func get_max(): Float64 {
        var max = this.data[0]
        for (i in 1..this.data.size) {
            if (this.data[i] > max) {
                max = this.data[i]
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        let mean = this.get_sum() / this.data.size.toFloat64()
        var sum_sq = 0.0
        for (i in 0..this.data.size) {
            sum_sq += (this.data[i] - mean) * (this.data[i] - mean)
        }
        return round((sum_sq / this.data.size.toFloat64()) * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        return round(sqrt(this.get_variance()) * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        if (this.data.size < 2) {
            return 1.0
        }

        let n = this.data.size.toFloat64()
        var sum_x = 0.0
        var sum_y = 0.0
        var sum_xy = 0.0
        var sum_x2 = 0.0
        var sum_y2 = 0.0

        for (i in 0..this.data.size) {
            let x = i.toFloat64()
            let y = this.data[i]
            sum_x += x
            sum_y += y
            sum_xy += x * y
            sum_x2 += x * x
            sum_y2 += y * y
        }

        let numerator = n * sum_xy - sum_x * sum_y
        let denominator = sqrt((n * sum_x2 - sum_x * sum_x) * (n * sum_y2 - sum_y * sum_y))

        return if (denominator == 0.0) { 
            1.0 
        } else { 
            abs(numerator / denominator) 
        }
    }
}

