            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        let mean = this.get_sum() / this.data.size.toFloat64()
        var variance = 0.0
        for (item in this.data) {
            variance += (item - mean) * (item - mean)
        }
        variance /= this.data.size.toFloat64()
        return round(variance * 100) / 100
    }

    public func get_std_deviation(): Float64 {
        let variance = this.get_variance()
