class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        assert(n == data2.size, "Data sizes must match")

        let sum1 = data1.reduce(0.0, {a, b => a + b})
        let sum2 = data2.reduce(0.0, {a, b => a + b})

        let sum1_sq = data1.reduce(0.0, {a, b => a + b * b})
        let sum2_sq = data2.reduce(0.0, {a, b => a + b * b})

        let p_sum = (0..n).reduce(0.0, {a, i => a + data1[i] * data2[i]})

        let num = p_sum - (sum1 * sum2 / n)
        let den = sqrt((sum1_sq - sum1 * sum1 / n) * (sum2_sq - sum2 * sum2 / n))

        return num / den
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        let mean = data.reduce(0.0, {a, b => a + b}) / n

        let variance = data.reduce(0.0, {a, b => a + pow(b - mean, 2)}) / n
        let std_dev = sqrt(variance)

        let skew = data.reduce(0.0, {a, b => a + pow((b - mean) / std_dev, 3)}) / n
        return skew
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        let mean = data.reduce(0.0, {a, b => a + b}) / n

        let variance = data.reduce(0.0, {a, b => a + pow(b - mean, 2)}) / n
        let std_dev = sqrt(variance)

        let kurt = data.reduce(0.0, {a, b => a + pow((b - mean) / std_dev, 4)}) / n - 3.0
        return kurt
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let root_two_pi = sqrt(2.0 * 3.141592653589793)
        let coeff = 1.0 / (sigma * root_two_pi)

        let pdf_values = ArrayList<Float64>([])
        for (x in data) {
            let exponent = -0.5 * pow((x - mu) / sigma, 2)
            pdf_values.add(coeff * exp(exponent))
        }
        return pdf_values
    }
}

