        let mean = data.reduce(0.0, {acc, x => acc + x}) / n.toFloat64()

        let sum_quad_diff = data.reduce(0.0, {acc, x => acc + (x - mean).pow(4.0)})
        let variance = data.reduce(0.0, {acc, x => acc + (x - mean).pow(2.0)}) / n.toFloat64()

