    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let factor = 1.0 / (sigma * sqrt(2.0 * Float64.pi))
        let result = ArrayList<Float64>([])

        for (x in data) {
            let exponent = -0.5 * ((x - mu) / sigma).pow(2.0)
            result.add(factor * exp(exponent))
        }

        return result
    }
