        let mut sum_x = 0.0
        let mut sum_y = 0.0
        let mut sum_xy = 0.0
        let mut sum_x2 = 0.0
        let mut sum_y2 = 0.0

        for (i in 0..n) {
            let x = data1[i]
            let y = data2[i]
            sum_x += x
            sum_y += y
            sum_xy += x * y
            sum_x2 += x * x
            sum_y2 += y * y
        }

        let numerator = sum_xy - (sum_x * sum_y) / n.toFloat64()
        let denominator = sqrt((sum_x2 - (sum_x * sum_x) / n.toFloat64()) * 
                              (sum_y2 - (sum_y * sum_y) / n.toFloat64()))
        return numerator / denominator
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        let mean = data.sum() / n.toFloat64()

        let mut sum_cubed_deviations = 0.0
        let mut sum_squared_deviations = 0.0

        for (x in data) {
            let deviation = x - mean
            sum_cubed_deviations += deviation * deviation * deviation
            sum_squared_deviations += deviation * deviation
        }

        let m3 = sum_cubed_deviations / n.toFloat64()
        let m2 = sqrt(sum_squared_deviations / n.toFloat64())

        return m3 / (m2 * m2 * m2)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        let mean = data.sum() / n.toFloat64()

        let mut sum_quad_deviations = 0.0
        let mut sum_squared_deviations = 0.0

        for (x in data) {
            let deviation = x - mean
            sum_quad_deviations += deviation * deviation * deviation * deviation
            sum_squared_deviations += deviation * deviation
        }

        let m4 = sum_quad_deviations / n.toFloat64()
        let m2 = sum_squared_deviations / n.toFloat64()

        return (m4 / (m2 * m2)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let sqrt_two_pi = sqrt(2.0 * 3.141592653589793)
        let mut result = ArrayList<Float64>()

        for (x in data) {
            let exponent = -0.5 * ((x - mu) / sigma) * ((x - mu) / sigma)
            let value = exp(exponent) / (sigma * sqrt_two_pi)
            result.add(value)
        }

        return result
    }

    // Helper function to calculate sum of ArrayList<Float64>
    private static func sum(data: ArrayList<Float64>): Float64 {
        let mut total = 0.0
        for (x in data) {
            total += x
        }
        return total
    }
