        return sum / data.size
    }

    private static func variance(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let sum = data.reduce(0.0, {acc, x => acc + (x - m) * (x - m)})
        return sum / data.size
    }

    private static func std_dev(data: ArrayList<Float64>): Float64 {
        return sqrt(variance(data))
    }

    private static func covariance(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let m1 = mean(data1)
        let m2 = mean(data2)
        let sum = (0..data1.size).reduce(0.0, {acc, i => acc + (data1[i] - m1) * (data2[i] - m2)})
        return sum / data1.size
    }

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let cov = covariance(data1, data2)
        let std1 = std_dev(data1)
        let std2 = std_dev(data2)
        return cov / (std1 * std2)
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let n = data.size
        let sum3 = data.reduce(0.0, {acc, x => acc + ((x - m) * (x - m) * (x - m))})
        let s3 = std_dev(data) * std_dev(data) * std_dev(data)
        return (sum3 / n) / s3
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let n = data.size
        let sum4 = data.reduce(0.0, {acc, x => acc + ((x - m) * (x - m) * (x - m) * (x - m))})
        let s4 = variance(data) * variance(data)
        return (sum4 / n) / s4 - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
