class DataStatistics4 {

    private static func mean(data: ArrayList<Float64>): Float64 {
        let sum = data.fold(0.0, {acc, x => acc + x})
        return sum / data.size.toFloat64()
    }

    private static func stdev(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let variance = data.fold(0.0, {acc, x => acc + pow(x - m, 2.0)}) / data.size.toFloat64()
        return sqrt(variance)
    }

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        if (n != data2.size || n == 0) {
            return 0.0
        }

        let mean1 = mean(data1)
        let mean2 = mean(data2)

        var covariance = 0.0
        var stdev1_sq = 0.0
        var stdev2_sq = 0.0

        for (i in 0..n) {
            let dx = data1[i] - mean1
            let dy = data2[i] - mean2
            covariance += dx * dy
            stdev1_sq += dx * dx
            stdev2_sq += dy * dy
        }

        return covariance / (sqrt(stdev1_sq) * sqrt(stdev2_sq))
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let s = stdev(data)
        let n = data.size.toFloat64()

        let moment = data.fold(0.0, {acc, x => acc + pow((x - m) / s, 3.0)})
        return moment * n / ((n - 1.0) * (n - 2.0))
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let s = stdev(data)
        let n = data.size.toFloat64()

        let moment = data.fold(0.0, {acc, x => acc + pow((x - m) / s, 4.0)})
        let term1 = moment * n * (n + 1.0) / ((n - 1.0) * (n - 2.0) * (n - 3.0))
        let term2 = 3.0 * pow(n - 1.0, 2.0) / ((n - 2.0) * (n - 3.0))
        return term1 - term2
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let sqrt_2pi = sqrt(2.0 * 3.141592653589793)
        let denominator = sigma * sqrt_2pi

        let result = ArrayList<Float64>([])
        for (x in data) {
            let exponent = -0.5 * pow((x - mu) / sigma, 2.0)
            result.add(exp(exponent) / denominator)
        }
        return result
    }
}

