        }

        let mean1 = mean(data1)
        let mean2 = mean(data2)
        var cov = 0.0
        var var1 = 0.0
        var var2 = 0.0

        for (i in 0..data1.size) {
            let diff1 = data1[i] - mean1
            let diff2 = data2[i] - mean2
            cov += diff1 * diff2
            var1 += diff1 * diff1
            var2 += diff2 * diff2
        }

        return cov / sqrt(var1 * var2)
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        if (data.size < 3) {
            return 0.0
        }

        let m = mean(data)
        let s = std_dev(data)
        let n = data.size.toFloat64()
        let sum = data.reduce(0.0, {acc, x => acc + pow((x - m)/s, 3)})
        return (n / ((n - 1) * (n - 2))) * sum
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        if (data.size < 4) {
            return 0.0
        }

        let m = mean(data)
        let s = std_dev(data)
        let n = data.size.toFloat64()
        let sum = data.reduce(0.0, {acc, x => acc + pow((x - m)/s, 4)})
        return ((n * (n + 1)) / ((n - 1) * (n - 2) * (n - 3))) * sum - (3 * pow(n - 1, 2) / ((n - 2) * (n - 3)))
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coeff = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        let result = ArrayList<Float64>([])

        for (x in data) {
            let exponent = -0.5 * pow((x - mu) / sigma, 2)
            result.add(coeff * exp(exponent))
        }

        return result
    }
}

