            sum_sq_dev += pow(dev, 2.0)
        }

        let sd_sq = sum_sq_dev / Float64(n)
        return (sum_quad_dev / Float64(n)) / pow(sd_sq, 2.0) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let sqrt_2pi = sqrt(2.0 * 3.141592653589793)
        let results = ArrayList<Float64>()
        let sigma_sq = pow(sigma, 2.0)

