class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'
        */
        let letters = ciphertext.toRuneArray()
        var result = ArrayList<Rune>()
        for (letter in letters) {
            if (letter >= r'a' && letter <= r'z') {
                let shifted = r'a' + ((letter - r'a' - shift + 26) % 26)
                result.add(shifted)
            } else if (letter >= r'A' && letter <= r'Z') {
                let shifted = r'A' + ((letter - r'A' - shift + 26) % 26)
                result.add(shifted)
            } else {
                result.add(letter)
            }
        }
        return String.fromRuneArray(result.toArray())
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'
        */
        let cipher_runes = ciphertext.toRuneArray()
        let key_runes = this.key.toRuneArray()
        var result = ArrayList<Rune>()
        var key_index = 0
        for (i in 0..cipher_runes.size) {
            let c = cipher_runes[i]
            if (c >= r'a' && c <= r'z') {
                let k = key_runes[key_index % key_runes.size] - r'a'
                let p = r'a' + ((c - r'a' - k + 26) % 26)
                result.add(p)
                key_index += 1
            } else if (c >= r'A' && c <= r'Z') {
                let k = key_runes[key_index % key_runes.size] - r'A'
                let p = r'A' + ((c - r'A' - k + 26) % 26)
                result.add(p)
                key_index += 1
            } else {
                result.add(c)
            }
        }
        return String.fromRuneArray(result.toArray())
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'
        */
        let n = encrypted_text.size()
        if (rails == 1 || n <= rails) {
            return encrypted_text
        }

        var fence = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            fence.add(ArrayList<Rune>())
        }

        var cycle = 2 * rails - 2
        for (i in 0..n) {
            let pos = i % cycle
            let rail = if (pos < rails) { pos } else { cycle - pos }
            fence[rail].add(encrypted_text.toRuneArray()[i])
        }

        let read_order = ArrayList<Int64>()
        var direction = 1
        var current_row = 0
        for (i in 0..n) {
            read_order.add(current_row)
            current_row += direction
            if (current_row == rails - 1 || current_row == 0) {
                direction *= -1
            }
        }

        var result = ArrayList<Rune>()
        var indices = ArrayList<Int64>([0]).fill(rails, 0)
        for (row in read_order) {
            if (indices[row] < fence[row].size) {
                result.add(fence[row][indices[row]])
                indices[row] += 1
            }
        }

        return String.fromRuneArray(result.toArray())
    }
}

