                result.add(shifted.char(), at: result.size)
            } else if (ch >= r'A' && ch <= r'Z') {
                let shifted = ((ch - r'A' - shift + alphabets) % alphabets) + r'A'
                result.add(shifted.char(), at: result.size)
            } else {
