        >>> d.vigenere_decipher('ifmmp')
        'ybocl'
        */
        var key_pointer = 0
        var result = ArrayList<Rune>([])
        let key_repeated = this.key.toRuneArray()
        for (ch in ciphertext.toRuneArray()) {
            if (ch >= r'a' && ch <= r'z') {
                let shift = key_repeated[key_pointer % key_repeated.size] - r'a'
                let decrypted = ((ch - r'a' - shift + 26) % 26) + r'a'
                result.add(decrypted.char(), at: result.size)
                key_pointer += 1
            } else if (ch >= r'A' && ch <= r'Z') {
                let shift = key_repeated[key_pointer % key_repeated.size] - r'A'
                let decrypted = ((ch - r'A' - shift + 26) % 26) + r'A'
                result.add(decrypted.char(), at: result.size)
