        */
        let n = encrypted_text.toRuneArray().size
        var rail_pattern = ArrayList<Int64>([])
        var down = false
        var rail = 0
        for (i in 0..n) {
            rail_pattern.add(rail, at: i)
            if (rail == 0 || rail == rails - 1) {
                down = !down
            }
            rail = if (down) { rail + 1 } else { rail - 1 }
        }

        var cipher_arr = encrypted_text.toRuneArray()
        var result = ArrayList<(Int64, Rune)>([])
        for (rail in 0..rails) {
            for (j in 0..n) {
                if (rail_pattern[j] == rail) {
                    result.add((j, cipher_arr[result.size]), at: result.size)
                }
            }
        }

        sort(result, key: {i: (Int64, Rune) => i[0]})
        var plaintext = ArrayList<Rune>([])
        for (pair in result) {
            plaintext.add(pair[1].char(), at: plaintext.size)
        }
        return String.fromRuneArray(plaintext)
    }
