class EncryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        let result = ArrayList<Rune>()
        let runes = plaintext.toRuneArray()

        for (c in runes) {
            let base = if (r'a' <= c && c <= r'z') { r'a'.toInt() }
                       else if (r'A' <= c && c <= r'Z') { r'A'.toInt() }
                       else { -1 }

            if (base == -1) {
                result.add(c)
                continue
            }

            let original_pos = c.toInt() - base
            let new_pos = (original_pos + shift) % 26
            let new_char = Rune.fromInt(base + new_pos)
            result.add(new_char)
        }

        return result.join("")
    }

    public func vigenere_cipher(plain_text: String): String {
        let result = ArrayList<Rune>()
        let plain_runes = plain_text.toRuneArray()
        let key_runes = this.key.toRuneArray()
        let key_length = key_runes.size

        for (i in 0..plain_runes.size) {
            let plain_c = plain_runes[i]
            let key_c = key_runes[i % key_length]

            let base_plain = if (r'a' <= plain_c && plain_c <= r'z') { r'a'.toInt() }
                             else if (r'A' <= plain_c && plain_c <= r'Z') { r'A'.toInt() }
                             else { -1 }

            let base_key = if (r'a' <= key_c && key_c <= r'z') { r'a'.toInt() }
                           else if (r'A' <= key_c && key_c <= r'Z') { r'A'.toInt() }
                           else { -1 }

            if (base_plain == -1 || base_key == -1) {
                result.add(plain_c)
                continue
            }

            let plain_pos = plain_c.toInt() - base_plain
            let key_pos = key_c.toInt() - base_key
            let new_pos = (plain_pos + key_pos) % 26
            let new_char = Rune.fromInt(base_plain + new_pos)
            result.add(new_char)
        }

        return result.join("")
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        if (rails == 1) {
            return plain_text
        }

        let rail_map = ArrayList<ArrayList<Rune>>()
        for (_ in 0..rails) {
            rail_map.add(ArrayList<Rune>())
        }

        let runes = plain_text.toRuneArray()
        var direction_down = false
        var rail = 0

        for (c in runes) {
            rail_map[rail].add(c)

            if (rail == 0 || rail == rails - 1) {
                direction_down = !direction_down
            }

            rail += if (direction_down) { 1 } else { -1 }
        }

        let result = ArrayList<Rune>()
        for (rail_list in rail_map) {
            result.addAll(rail_list)
        }

        return result.join("")
    }
}

