        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        let chars = plaintext.toRuneArray()
        let mut result = ArrayList<Rune>()

        for (c in chars) {
            if (c >= r'a' && c <= r'z') {
                let base = r'a'.toInt64()
                let shifted = ((c.toInt64() - base + shift) % 26 + base)
                result.add(Rune(shifted))
            } else if (c >= r'A' && c <= r'Z') {
                let base = r'A'.toInt64()
                let shifted = ((c.toInt64() - base + shift) % 26 + base)
                result.add(Rune(shifted))
            } else {
                result.add(c)
            }
        }

        return String.fromRuneArray(result)
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        let plain_chars = plain_text.toRuneArray()
        let key_chars = this.key.toRuneArray()
        let mut result = ArrayList<Rune>()
        let mut key_index = 0

        for (plain_char in plain_chars) {
            if (plain_char >= r'a' && plain_char <= r'z') {
                let plain_offset = plain_char.toInt64() - r'a'.toInt64()
                let key_char = key_chars[key_index % key_chars.size]
                let key_offset = key_char.toInt64() - r'a'.toInt64()
                let cipher_offset = (plain_offset + key_offset) % 26
                result.add(Rune(r'a'.toInt64() + cipher_offset))
                key_index += 1
            } else if (plain_char >= r'A' && plain_char <= r'Z') {
                let plain_offset = plain_char.toInt64() - r'A'.toInt64()
                let key_char = key_chars[key_index % key_chars.size]
                let key_offset = key_char.toLower().toInt64() - r'a'.toInt()
                let cipher_offset = (plain_offset + key_offset) % 26
                result.add(Rune(r'A'.toInt64() + cipher_offset))
                key_index += 1
            } else {
                result.add(plain_char)
            }
        }

        return String.fromRuneArray(result)
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        if (rails == 1) {
            return plain_text
        }

        let chars = plain_text.toRuneArray()
        let mut rail_rows = ArrayList<ArrayList<Rune>>()

        for (i in 0..rails) {
            rail_rows.add(ArrayList<Rune>())
        }

        var current_rail = 0
        var going_down = true

        for (c in chars) {
            rail_rows[current_rail].add(c)
            if (going_down) {
                if (current_rail == rails - 1) {
                    going_down = false
                    current_rail -= 1
                } else {
                    current_rail += 1
                }
            } else {
                if (current_rail == 0) {
                    going_down = true
                    current_rail += 1
                } else {
                    current_rail -= 1
                }
            }
        }

        let mut result = ArrayList<Rune>()
        for (rail in rail_rows) {
            result.addAll(rail)
        }

        return String.fromRuneArray(result)
    }
}

