            let lower_k = k_rune.toLower() - r'a'
            let lower_p = p_rune.toLower() - r'a'
            let encrypted = (lower_p + lower_k) %% 26 + r'a'
            result.add(encrypted)
            i = i + 1
        }
        return result.toRuneArray().toString()
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
