        for (rune in runes) {
            rail_strings[rail].add(rune)
            if (rail == 0 || rail == rails - 1) {
                down = !down
            }
            rail = if (down) { rail + 1 } else { rail - 1 }
        }

        let result = ArrayList<Rune>()
        for (rail_list in rail_strings) {
            result.addAll(rail_list)
        }
        return result.toRuneArray().toString()
