import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        this.prepare(expression)
        let stack = ArrayList<Decimal>()
        for token in postfix_stack {
            if (!is_operator(token)) {
                stack.add(Decimal.parse(token))
            } else {
                let second = stack.remove(at: stack.size - 1)
                let first = stack.remove(at: stack.size - 1)
                stack.add(_calculate(first, second, token))
            }
        }
        return stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        let transformed = ExpressionCalculator.transform(expression)
        let stack = ArrayList<String>()
        let chars = transformed.toRuneArray()
        var idx = 0

        while (idx < chars.size) {
            let c = chars[idx].toString()
            if (c == " ") {
                idx += 1
                continue
            }

            if (!is_operator(c)) {
                var num = ""
                while (idx < chars.size && !is_operator(chars[idx].toString())) {
                    num += chars[idx].toString()
                    idx += 1
                }
                postfix_stack.add(num)
            } else {
                if (stack.size == 0 || c == "(") {
                    stack.add(c)
                } else {
                    if (c == ")") {
                        while (stack.size > 0 && stack[stack.size - 1] != "(") {
                            postfix_stack.add(stack.remove(at: stack.size - 1))
                        }
                        stack.remove(at: stack.size - 1)
                    } else {
                        while (stack.size > 0 && compare(c, stack[stack.size - 1])) {
                            postfix_stack.add(stack.remove(at: stack.size - 1))
                        }
                        stack.add(c)
                    }
                }
                idx += 1
            }
        }

        while (stack.size > 0) {
            postfix_stack.add(stack.remove(at: stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        match (c) {
            case "+" => true
            case "-" => true
            case "*" => true
            case "/" => true
            case "(" => true
            case ")" => true
            case "%" => true
            case _ => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
        let op_list = ["%", "*", "/", "+", "-", "(", ")"]
        let cur_idx = op_list.indexOf(cur) ?? -1
        let peek_idx = op_list.indexOf(peek) ?? -1
        operat_priority[cur_idx] >= operat_priority[peek_idx]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => Decimal(0)
        }
    }

    public static func transform(expression: String): String {
        let regex = Regex("\\s+")
        regex.replaceAll(expression, "")
    }
}

