        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression)
        let temp_stack = ArrayList<Decimal>()
        for s in postfix_stack {
            if is_operator(s) {
                let second_value = temp_stack.pop()
                let first_value = temp_stack.pop()
                temp_stack.add(_calculate(first_value, second_value, s))
            } else {
                temp_stack.add(Decimal(s))
            }
        }
        return temp_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let op_stack = ArrayList<String>()
        let transformed_exp = transform(expression)
        let num_str = ""

        for c in transformed_exp.runes() {
            let s = String(c)
            if s == " " {
                continue
            } else if is_operator(s) {
                if num_str.size > 0 {
                    postfix_stack.add(num_str)
                    num_str = ""
                }
                if s == "(" {
                    op_stack.add(s)
                } else if s == ")" {
                    while op_stack.size > 0 && op_stack[op_stack.size - 1] != "(" {
                        postfix_stack.add(op_stack.pop())
                    }
                    op_stack.pop()
                } else {
                    while op_stack.size > 0 && compare(s, op_stack[op_stack.size - 1]) {
                        postfix_stack.add(op_stack.pop())
                    }
                    op_stack.add(s)
                }
            } else {
                num_str += s
            }
        }

        if num_str.size > 0 {
            postfix_stack.add(num_str)
        }

        while op_stack.size > 0 {
            postfix_stack.add(op_stack.pop())
        }
