            case "/" => 3
            case "(" => 4
            case ")" => 5
            case "%" => 6
            case _ => 7
        }
        let peek_index = match (peek) {
            case "+" => 0
            case "-" => 1
            case "*" => 2
            case "/" => 3
            case "(" => 4
            case ")" => 5
            case "%" => 6
            case _ => 7
        }
        operat_priority[op_index] >= operat_priority[peek_index]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
