class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression)
        let operand_stack = ArrayList<Decimal>()
        for token in postfix_stack {
            if (!is_operator(token)) {
                operand_stack.add(Decimal.parse(token))
            } else {
                let second = operand_stack.remove(at: operand_stack.size - 1)
                let first = operand_stack.remove(at: operand_stack.size - 1)
                operand_stack.add(_calculate(first, second, token))
            }
        }
        return operand_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let transformed = transform(expression)
        let operator_stack = ArrayList<String>()
        let regex = Regex("\\d+\\.?\\d*|[\\+\\-\\*/%\\(\\)]")
        let tokens = regex.findAll(transformed)

        for token in tokens {
            if (!is_operator(token)) {
                postfix_stack.add(token)
            } else {
                if (token == "(") {
                    operator_stack.add(token)
                } else if (token == ")") {
                    while (operator_stack[operator_stack.size - 1] != "(") {
                        postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                    }
                    operator_stack.remove(at: operator_stack.size - 1)
                } else {
                    while (operator_stack.size > 0 && 
                           compare(token, operator_stack[operator_stack.size - 1])) {
                        postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                    }
                    operator_stack.add(token)
                }
            }
        }
        while (operator_stack.size > 0) {
            postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        match (c) {
            case "+" | "-" | "*" | "/" | "(" | ")" | "%" => true
            case _ => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_idx = match (cur) {
            case "(" => 0
            case "+" => 1
            case "-" => 2
            case "*" => 3
            case "/" => 4
            case ")" => 5
            case "%" => 6
            case _ => -1
        }
        let peek_idx = match (peek) {
            case "(" => 0
            case "+" => 1
            case "-" => 2
            case "*" => 3
            case "/" => 4
            case ")" => 5
            case "%" => 6
            case _ => -1
        }
        operat_priority[cur_idx] >= operat_priority[peek_idx]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => throw "Unsupported operator"
        }
    }

    public static func transform(expression: String): String {
        let regex = Regex("\\s+")
        regex.replaceAll(expression, "")
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        let op_stack = ArrayList<String>()
        let num_stack = ArrayList<Decimal>()
        let expr_arr = expression.split(" ")

        for token in expr_arr {
            if (is_operator(token)) {
                while (!op_stack.isEmpty() && compare(op_stack.last(), token)) {
                    let op = op_stack.pop()
                    let num2 = num_stack.pop()
                    let num1 = num_stack.pop()
                    num_stack.push(_calculate(num1, num2, op))
                }
                op_stack.push(token)
            } else {
                num_stack.push(Decimal.parse(token))
            }
        }

        while (!op_stack.isEmpty()) {
            let op = op_stack.pop()
            let num2 = num_stack.pop()
            let num1 = num_stack.pop()
            num_stack.push(_calculate(num1, num2, op))
        }

        return num_stack.pop().toFloat64()
    }

    public func prepare(expression: String): Unit {
        let op_stack = ArrayList<String>()
        let transformed = transform(expression)

        let i = 0
        while (i < transformed.size()) {
            let c = transformed[i]
            if (is_operator(c.toString())) {
                let operator1 = c.toString()
                if (operator1 == ")") {
                    while (op_stack.last() != "(") {
                        postfix_stack.add(op_stack.pop())
                    }
                    op_stack.pop()
                } else if (operator1 == "(") {
                    op_stack.push(operator1)
                } else {
                    while (!op_stack.isEmpty() && compare(op_stack.last(), operator1)) {
                        postfix_stack.add(op_stack.pop())
                    }
                    op_stack.push(operator1)
                }
            } else {
                let num_str = ""
                while (i < transformed.size() && !is_operator(transformed[i].toString())) {
                    num_str += transformed[i].toString()
                    i += 1
                }
                postfix_stack.add(num_str)
                i -= 1
            }
            i += 1
        }

        while (!op_stack.isEmpty()) {
            postfix_stack.add(op_stack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        return ["+", "-", "*", "/", "(", ")", "%"].contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_idx = ["+", "-", "*", "/", "(", ")", "%"].indexOf(cur)
        let peek_idx = ["+", "-", "*", "/", "(", ")", "%"].indexOf(peek)
        if (cur_idx < 0 || peek_idx < 0) {
            return false
        }
        return operat_priority[cur_idx] >= operat_priority[peek_idx]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => return first_value + second_value
            case "-" => return first_value - second_value
            case "*" => return first_value * second_value
            case "/" => return first_value / second_value
            case "%" => return first_value % second_value
            case _ => return Decimal(0)
        }
    }

    public static func transform(expression: String): String {
        return expression.replaceAll(Regex("\\s+"), "")
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.stack.Stack

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        this.prepare(expression)
        let stack = Stack<Decimal>()
        for token in this.postfix_stack {
            if ExpressionCalculator.is_operator(token) {
                let second = stack.pop()
                let first = stack.pop()
                stack.push(ExpressionCalculator._calculate(first, second, token))
            } else {
                stack.push(Decimal.parse(token))
            }
        }
        return stack.pop().toFloat64()
    }

    public func prepare(expression: String): Unit {
        this.postfix_stack.clear()
        let transformed = ExpressionCalculator.transform(expression)
        let op_stack = Stack<String>()
        let regex = Regex("\\d+|\\(|\\)|\\+|-|\\*|/|%")
        for token in regex.findAll(transformed) {
            if ExpressionCalculator.is_operator(token) {
                if (token == ")") {
                    while (op_stack.peek() != "(") {
                        this.postfix_stack.add(op_stack.pop())
                    }
                    op_stack.pop()
                } else if (token == "(" || op_stack.isEmpty() || !this.compare(token, op_stack.peek())) {
                    op_stack.push(token)
                } else {
                    while (!op_stack.isEmpty() && this.compare(token, op_stack.peek())) {
                        this.postfix_stack.add(op_stack.pop())
                    }
                    op_stack.push(token)
                }
            } else {
                this.postfix_stack.add(token)
            }
        }
        while (!op_stack.isEmpty()) {
            this.postfix_stack.add(op_stack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        match (c) {
            case "+" => true
            case "-" => true
            case "*" => true
            case "/" => true
            case "(" => true
            case ")" => true
            case "%" => true
            case _ => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_idx = match (cur) {
            case "+" => 0
            case "-" => 1
            case "*" => 2
            case "/" => 3
            case "(" => 4
            case ")" => 5
            case "%" => 6
            case _ => 7
        }
        let peek_idx = match (peek) {
            case "+" => 0
            case "-" => 1
            case "*" => 2
            case "/" => 3
            case "(" => 4
            case ")" => 5
            case "%" => 6
            case _ => 7
        }
        this.operat_priority[cur_idx] <= this.operat_priority[peek_idx]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => throw "Invalid operator"
        }
    }

    public static func transform(expression: String): String {
        expression.replace(" ", "")
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        this.prepare(expression)
        let temp_stack = ArrayList<Decimal>()

        for element in this.postfix_stack {
            if (!ExpressionCalculator.is_operator(element)) {
                temp_stack.add(Decimal(element))
            } else {
                let second = temp_stack.remove(at: temp_stack.size - 1)
                let first = temp_stack.remove(at: temp_stack.size - 1)
                temp_stack.add(ExpressionCalculator._calculate(first, second, element))
            }
        }
        return temp_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        this.postfix_stack.clear()
        let operator_stack = ArrayList<String>()
        let transformed = ExpressionCalculator.transform(expression)
        let re = Regex("\\d+\\.?\\d*|[\\(\\)\\+\\-\\*/%]")
        let tokens = re.findAll(transformed)

        for token in tokens {
            if (!ExpressionCalculator.is_operator(token)) {
                this.postfix_stack.add(token)
            } else if (token == "(") {
                operator_stack.add(token)
            } else if (token == ")") {
                while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                    this.postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                operator_stack.remove(at: operator_stack.size - 1) // Remove "("
            } else {
                while (operator_stack.size > 0 && this.compare(operator_stack[operator_stack.size - 1], token)) {
                    this.postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                operator_stack.add(token)
            }
        }

        while (operator_stack.size > 0) {
            this.postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        match (c) {
            case "+" => true
            case "-" => true
            case "*" => true
            case "/" => true
            case "(" => true
            case ")" => true
            case "%" => true
            case _ => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
        let op_map = HashMap<String, Int64>([
            ("+", 1), ("-", 2), ("*", 3), 
            ("/", 4), ("(", 5), (")", 6), 
            ("%", 7)
        ])
        let cur_pri = this.operat_priority[op_map[cur] ?? 0]
        let peek_pri = this.operat_priority[op_map[peek] ?? 0]
        cur_pri >= peek_pri
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => throw Exception("Invalid operator")
        }
    }

    public static func transform(expression: String): String {
        expression.replace(" ", "")
    }
}

