import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        this.prepare(expression)
        let temp_stack = ArrayList<Decimal>()

        for item in postfix_stack {
            if (ExpressionCalculator.is_operator(item)) {
                let second = temp_stack.remove(at: temp_stack.size - 1)
                let first = temp_stack.remove(at: temp_stack.size - 1)
                let result = ExpressionCalculator._calculate(first, second, item)
                temp_stack.add(result)
            } else {
                temp_stack.add(Decimal.parse(item))
            }
        }

        return temp_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        let transformed = ExpressionCalculator.transform(expression)
        let operator_stack = ArrayList<String>()

        let mut i = 0
        while (i < transformed.size) {
            let c = transformed[i].toString()
            if (c == " ") {
                i += 1
                continue
            }

            if (ExpressionCalculator.is_operator(c)) {
                if (operator_stack.size == 0) {
                    operator_stack.add(c)
                } else {
                    if (this.compare(c, operator_stack[operator_stack.size - 1])) {
                        operator_stack.add(c)
                    } else {
                        if (c == ")") {
                            while (operator_stack[operator_stack.size - 1] != "(") {
                                postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                            }
                            operator_stack.remove(at: operator_stack.size - 1)
                        } else {
                            while (operator_stack.size > 0 && !this.compare(c, operator_stack[operator_stack.size - 1])) {
                                postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                            }
                            operator_stack.add(c)
                        }
                    }
                }
                i += 1
            } else {
                let mut num = ""
                while (i < transformed.size && !ExpressionCalculator.is_operator(transformed[i].toString()) && transformed[i] != ' ') {
                    num += transformed[i].toString()
                    i += 1
                }
                postfix_stack.add(num)
            }
        }

        while (operator_stack.size > 0) {
            postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        match (c) {
            case "+" => true
            case "-" => true
            case "*" => true
            case "/" => true
            case "(" => true
            case ")" => true
            case "%" => true
            case _ => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_index = match (cur) {
            case "(" => 0
            case "+" => 1
            case "-" => 2
            case "*" => 3
            case "/" => 4
            case "%" => 5
            case ")" => 6
            case _ => 7
        }

        let peek_index = match (peek) {
            case "(" => 0
            case "+" => 1
            case "-" => 2
            case "*" => 3
            case "/" => 4
            case "%" => 5
            case ")" => 6
            case _ => 7
        }

        operat_priority[cur_index] >= operat_priority[peek_index]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => Decimal(0)
        }
    }

    public static func transform(expression: String): String {
        let mut result = ""
        let mut i = 0
        while (i < expression.size) {
            if (expression[i] == ' ') {
                i += 1
                continue
            }
            result += expression[i].toString()
            i += 1
        }
        result
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs

class FitnessTracker {
    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        return this.weight / (this.height * this.height)
    }

    public func condition_judge(): Int64 {
        let bmi = this.get_BMI()
        let std_range = match (this.sex) {
            case "male" => this.BMI_std[0]["male"]
            case "female" => this.BMI_std[1]["female"]
            case _ => ArrayList<Int64>([0, 0])
        }
        if (bmi < Float64(std_range[0])) {
            return -1
        } else if (bmi > Float64(std_range[1])) {
            return 1
        } else {
            return 0
        }
    }

    public func calculate_calorie_intake(): Float64 {
        let bmr = match (this.sex) {
            case "male" => Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) + Float64(5)
            case "female" => Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) - Float64(161)
            case _ => Float64(0)
        }
        let condition = this.condition_judge()
        return match (condition) {
            case -1 => bmr * Float64(1.6)
            case 1 => bmr * Float64(1.2)
            case _ => bmr * Float64(1.4)
        }
    }
}

