import std.collection.HashMap

class Hotel {
    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        let available = available_rooms.get(room_type) ?? None<Int64>()
        if (available.isNone()) {
            return "false"
        }
        let avail_num = available.getOrThrow()
        if (room_number <= avail_num) {
            let booked_for_type = booked_rooms.get(room_type) ?? None<HashMap<String, Int64>>()
            var new_booked = if (booked_for_type.isNone()) {
                HashMap<String, Int64>()
            } else {
                booked_for_type.getOrThrow()
            }
            let current_booked = new_booked.get(name) ?? None<Int64>()
            let new_value = if (current_booked.isNone()) {
                room_number
            } else {
                current_booked.getOrThrow() + room_number
            }
            new_booked.add(name, new_value)
            booked_rooms.add(room_type, new_booked)
            available_rooms.add(room_type, avail_num - room_number)
            return "Success!"
        } else {
            if (avail_num == 0) {
                return "false"
            }
            return avail_num.toString()
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        let booked_for_type = booked_rooms.get(room_type) ?? None<HashMap<String, Int64>>()
        if (booked_for_type.isNone()) {
            return false
        }
        let type_bookings = booked_for_type.getOrThrow()
        let guest_booked = type_bookings.get(name) ?? None<Int64>()
        if (guest_booked.isNone()) {
            return false
        }
        let booked_num = guest_booked.getOrThrow()
        if (room_number > booked_num) {
            return false
        }
        if (room_number == booked_num) {
            type_bookings.remove(name)
        } else {
            type_bookings.add(name, booked_num - room_number)
        }
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        let current_available = available_rooms.get(room_type) ?? None<Int64>()
        let new_available = if (current_available.isNone()) {
            room_number
        } else {
            current_available.getOrThrow() + room_number
        }
        available_rooms.add(room_type, new_available)
    }

    public func get_available_rooms(room_type: String): Int64 {
        let available = available_rooms.get(room_type) ?? None<Int64>()
        if (available.isNone()) {
            return 0
        }
        return available.getOrThrow()
    }
}

