import std.collection.ArrayList

class Interpolation {
    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()

        for (xi in 0..x_interp.size) {
            let x_val = x_interp[xi]
            let mut idx = 0

            while (idx < x.size - 1 && x[idx + 1] < x_val) {
                idx += 1
            }

            if (idx == x.size - 1) {
                result.add(y[y.size - 1])
                continue
            }

            let x0 = x[idx]
            let x1 = x[idx + 1]
            let y0 = y[idx]
            let y1 = y[idx + 1]

            let slope = (y1 - y0) / (x1 - x0)
            let interp_y = y0 + slope * (x_val - x0)
            result.add(interp_y)
        }

        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()

        for (i in 0..x_interp.size) {
            let x_val = x_interp[i]
            let y_val = y_interp[i]

            // Find x interval
            let mut x_idx = 0
            while (x_idx < x.size - 1 && x[x_idx + 1] < x_val) {
                x_idx += 1
            }

            // Find y interval
            let mut y_idx = 0
            while (y_idx < y.size - 1 && y[y_idx + 1] < y_val) {
                y_idx += 1
            }

            if (x_idx == x.size - 1 || y_idx == y.size - 1) {
                result.add(z[y_idx][x_idx])
                continue
            }

            // Get corner points
            let x0 = x[x_idx]
            let x1 = x[x_idx + 1]
            let y0 = y[y_idx]
            let y1 = y[y_idx + 1]

            // Get z values at corners
            let z00 = z[y_idx][x_idx]
            let z01 = z[y_idx][x_idx + 1]
            let z10 = z[y_idx + 1][x_idx]
            let z11 = z[y_idx + 1][x_idx + 1]

            // Interpolate along x-axis first
            let slope_x0 = (z01 - z00) / (x1 - x0)
            let slope_x1 = (z11 - z10) / (x1 - x0)

            let z_x0 = z00 + slope_x0 * (x_val - x0)
            let z_x1 = z10 + slope_x1 * (x_val - x0)

            // Then interpolate along y-axis
            let slope_y = (z_x1 - z_x0) / (y1 - y0)
            let interp_z = z_x0 + slope_y * (y_val - y0)

            result.add(interp_z)
        }

        return result
    }
}

import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>([])

        for (xi in x_interp) {
            var i = 0
            while (i < x.size - 1 && x[i + 1] < xi) {
                i = i + 1
            }

            if (i == x.size - 1) {
                result.add(y[y.size - 1])
            } else {
                let x0 = x[i]
                let x1 = x[i + 1]
                let y0 = y[i]
                let y1 = y[i + 1]
                let yi = y0 + (xi - x0) * (y1 - y0) / (x1 - x0)
                result.add(yi)
            }
        }

        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>([])

        for (k in 0..x_interp.size) {
            let xi = x_interp[k]
            let yi = y_interp[k]

            // Find x interval
            var i = 0
            while (i < x.size - 1 && x[i + 1] < xi) {
                i = i + 1
            }

            // Find y interval
            var j = 0
            while (j < y.size - 1 && y[j + 1] < yi) {
                j = j + 1
            }

            if (i == x.size - 1 || j == y.size - 1) {
                result.add(z[i][j])
            } else {
                // Bilinear interpolation
                let x0 = x[i]
                let x1 = x[i + 1]
                let y0 = y[j]
                let y1 = y[j + 1]

                let z00 = z[i][j]
                let z01 = z[i][j + 1]
                let z10 = z[i + 1][j]
                let z11 = z[i + 1][j + 1]

                // Interpolate in x direction first
                let z0 = z00 + (xi - x0) * (z10 - z00) / (x1 - x0)
                let z1 = z01 + (xi - x0) * (z11 - z01) / (x1 - x0)

                // Then interpolate in y direction
                let zi = z0 + (yi - y0) * (z1 - z0) / (y1 - y0)
                result.add(zi)
            }
        }

        return result
    }
}

