class Interpolation {
    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (xi in x_interp) {
            var idx = 0
            while (idx < x.size - 1 && x[idx + 1] < xi) {
                idx = idx + 1
            }
            if (idx == x.size - 1) {
                let x0 = x[idx - 1]
                let x1 = x[idx]
                let y0 = y[idx - 1]
                let y1 = y[idx]
                let slope = (y1 - y0) / (x1 - x0)
                result.add(y1 + slope * (xi - x1))
            } else {
                let x0 = x[idx]
                let x1 = x[idx + 1]
                let y0 = y[idx]
                let y1 = y[idx + 1]
                if (x0 == x1) {
                    result.add(y0)
                } else {
                    let slope = (y1 - y0) / (x1 - x0)
                    result.add(y0 + slope * (xi - x0))
                }
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            // Find x interval
            var x_idx = 0
            while (x_idx < x.size - 1 && x[x_idx + 1] < xi) {
                x_idx = x_idx + 1
            }

            // Find y interval
            var y_idx = 0
            while (y_idx < y.size - 1 && y[y_idx + 1] < yi) {
                y_idx = y_idx + 1
            }

            // Get four surrounding points
            let x0 = x[x_idx]
            let x1 = if (x_idx + 1 < x.size) { x[x_idx + 1] } else { x[x_idx] }
            let y0 = y[y_idx]
