            let z11 = if (x_idx + 1 < x.size && y_idx + 1 < y.size) { z[x_idx + 1][y_idx + 1] } else { z[x_idx][y_idx] }

            // Bilinear interpolation
            let x_ratio = if (x0 == x1) { 0.0 } else { (xi - x0) / (x1 - x0) }
            let y_ratio = if (y0 == y1) { 0.0 } else { (yi - y0) / (y1 - y0) }

            let temp1 = z00 * (1 - x_ratio) + z10 * x_ratio
            let temp2 = z01 * (1 - x_ratio) + z11 * x_ratio
            let interp_z = temp1 * (1 - y_ratio) + temp2 * y_ratio

            result.add(interp_z)
        }
        return result
    }
}

