class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            let octet = IntNative.tryFromStr(part)
            if (octet is None || octet.getOrThrow() < 0 || octet.getOrThrow() > 255) {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        let result = ArrayList<String>([])
        if (!is_valid()) {
            return result
        }
        result.addAll(ip_address.split("."))
        return result
    }

    public func get_binary(): String {
        if (!is_valid()) {
            return ""
        }
        let octets = get_octets()
        let binary_parts = ArrayList<String>([])
        for (octet_str in octets) {
            let octet = IntNative.fromStr(octet_str)
            let binary_str = octet.toStr(radix: 2)
            let padded = "0".repeat(8 - binary_str.size) + binary_str
            binary_parts.add(padded)
        }
        return binary_parts.join(".")
    }
}

