import std.collection.ArrayList

class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = this.ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            let num = part.toInt64()
            if (num == None<Int64>() || num.getOrThrow() < 0 || num.getOrThrow() > 255) {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        if (!this.is_valid()) {
            return ArrayList<String>([])
        }
        return ArrayList<String>(this.ip_address.split("."))
    }

    public func get_binary(): String {
        if (!this.is_valid()) {
            return ""
        }
        var binary_parts = ArrayList<String>()
        let octets = this.get_octets()
        for (octet in octets) {
            let num = octet.toInt64().getOrThrow()
            var binary = ""
            for (i in 7..0:-1) {
                binary = binary + if ((num & (1 << i)) != 0) { "1" } else { "0" }
            }
            binary_parts.add(binary)
        }
        return binary_parts.join(".")
    }
}

