import std.math.abs

class KappaCalculator {
    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var po: Float64 = 0.0
        var pe: Float64 = 0.0
        var total: Int64 = 0

        // Calculate total count and po (observed agreement)
        for (i in 0..k) {
            po += testData[i][i].toFloat64()
            for (j in 0..k) {
                total += testData[i][j]
            }
        }
        po = po / total.toFloat64()

        // Calculate pe (expected agreement)
        var rowSums = ArrayList<Int64>([])
        var colSums = ArrayList<Int64>([])

        for (i in 0..k) {
            rowSums.add(0)
            colSums.add(0)
        }

        for (i in 0..k) {
            for (j in 0..k) {
                rowSums[i] += testData[i][j]
                colSums[j] += testData[i][j]
            }
        }

        for (i in 0..k) {
            pe += rowSums[i].toFloat64() * colSums[i].toFloat64()
        }
        pe = pe / (total.toFloat64() * total.toFloat64())

        // Calculate Cohen's kappa
        return (po - pe) / (1.0 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var pj = ArrayList<Float64>([])
        var p_i = ArrayList<Float64>([])

        // Initialize pj array
        for (j in 0..k) {
            pj.add(0.0)
        }

        // Calculate pj values
        for (i in 0..N) {
            for (j in 0..k) {
                pj[j] += testData[i][j].toFloat64()
            }
        }

        for (j in 0..k) {
            pj[j] = pj[j] / (N.toFloat64() * n.toFloat64())
        }

        // Calculate p_i values
        for (i in 0..N) {
            var sum: Float64 = 0.0
            for (j in 0..k) {
                sum += testData[i][j].toFloat64() * testData[i][j].toFloat64()
            }
            p_i.add((sum - n.toFloat64()) / (n.toFloat64() * (n.toFloat64() - 1.0)))
        }

        // Calculate P-bar and Pe-bar
        var p_bar: Float64 = 0.0
        for (i in 0..N) {
            p_bar += p_i[i]
        }
        p_bar = p_bar / N.toFloat64()

        var pe_bar: Float64 = 0.0
        for (j in 0..k) {
            pe_bar += pj[j] * pj[j]
        }

        // Calculate Fleiss' kappa
        return (p_bar - pe_bar) / (1.0 - pe_bar)
    }
}

