class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var totalAgreements: Int64 = 0
        var totalObservations: Int64 = 0
        var expectedAgreements: Float64 = 0.0

        // Calculate observed agreements and total observations
        for (i in 0..k) {
            totalAgreements += testData[i][i]
            for (j in 0..k) {
                totalObservations += testData[i][j]
            }
        }

        // Calculate expected agreements
        for (i in 0..k) {
            var rowSum: Int64 = 0
            var colSum: Int64 = 0
            for (j in 0..k) {
                rowSum += testData[i][j]
                colSum += testData[j][i]
            }
            expectedAgreements += (rowSum.toFloat64() * colSum.toFloat64())
        }
        expectedAgreements /= (totalObservations * totalObservations).toFloat64()

        let po = totalAgreements.toFloat64() / totalObservations.toFloat64()
        let pe = expectedAgreements

        if (abs(1 - pe) < 0.000001) {
            return 1.0
        }

        return (po - pe) / (1 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var p: ArrayList<Float64> = ArrayList<Float64>([])
        var P: ArrayList<Float64> = ArrayList<Float64>([])

        // Calculate p_j
        for (j in 0..k) {
            var sumPj: Int64 = 0
            for (i in 0..N) {
                sumPj += testData[i][j]
            }
            p.add(sumPj.toFloat64() / (N * n).toFloat64())
        }

        // Calculate P_i
        for (i in 0..N) {
            var sumSquare: Int64 = 0
            var sumRatings: Int64 = 0
            for (j in 0..k) {
                let rating = testData[i][j]
                sumSquare += rating * rating
                sumRatings += rating
            }
            P.add((sumSquare.toFloat64() - n.toFloat64()) / (n.toFloat64() * (n.toFloat64() - 1)))
        }

        // Calculate P̄
        var Pbar: Float64 = 0.0
        for (value in P) {
            Pbar += value
        }
        Pbar /= N.toFloat64()

        // Calculate P̄e
        var Pe: Float64 = 0.0
        for (value in p) {
            Pe += value * value
        }

        if (abs(1 - Pe) < 0.000001) {
            return 1.0
        }

        return (Pbar - Pe) / (1 - Pe)
    }
}

