class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let p0 = calculateObservedAgreement(testData, k)
        let pe = calculateExpectedAgreement(testData, k)
        let kappaValue = (p0 - pe) / (1.0 - pe)
        return kappaValue
    }

    private static func calculateObservedAgreement(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var agreementSum: Float64 = 0.0
        var totalSum: Float64 = 0.0

        for (i in 0..testData.size) {
            agreementSum += testData[i][i].toFloat64()
            for (j in 0..testData[i].size) {
                totalSum += testData[i][j].toFloat64()
            }
        }

        return agreementSum / totalSum
    }

    private static func calculateExpectedAgreement(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var rowSums = ArrayList<Float64>()
        var colSums = ArrayList<Float64>()
        var totalSum: Float64 = 0.0

        // Initialize sums
        for (_ in 0..k) {
            rowSums.add(0.0)
            colSums.add(0.0)
        }

        // Calculate row and column sums
        for (i in 0..testData.size) {
            for (j in 0..testData[i].size) {
                let value = testData[i][j].toFloat64()
                rowSums[i] += value
                colSums[j] += value
                totalSum += value
            }
        }

        // Calculate expected agreement
        var pe: Float64 = 0.0
        for (i in 0..k) {
            pe += (rowSums[i] * colSums[i])
        }
        pe /= (totalSum * totalSum)

        return pe
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        let p = calculateAverageAgreement(testData, N, k, n)
        let pe = calculateRandomAgreement(testData, N, k, n)
        let kappaValue = (p - pe) / (1.0 - pe)
        return kappaValue
    }

    private static func calculateAverageAgreement(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var pSum: Float64 = 0.0

        for (i in 0..N) {
            var sumOverCategories: Float64 = 0.0
            for (j in 0..k) {
                let value = testData[i][j].toFloat64()
                sumOverCategories += value * value
            }
            let p_i = (sumOverCategories - n.toFloat64()) / (n.toFloat64() * (n.toFloat64() - 1.0))
            pSum += p_i
        }

        return pSum / N.toFloat64()
    }

    private static func calculateRandomAgreement(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var proportions = ArrayList<Float64>()
        var sumOverAllRatings: Float64 = 0.0

        // Initialize proportions
        for (_ in 0..k) {
            proportions.add(0.0)
        }

        // Calculate sum of proportions
        for (i in 0..N) {
            for (j in 0..k) {
                proportions[j] += testData[i][j].toFloat64()
            }
        }

        for (j in 0..k) {
            sumOverAllRatings += proportions[j]
        }

        // Calculate pe
        var peSum: Float64 = 0.0
        for (j in 0..k) {
            let p_j = proportions[j] / sumOverAllRatings
            peSum += p_j * p_j
        }

        return peSum
    }
}

