        for (i in 0..k) {
            expected += (rowSums[i].toFloat64() * colSums[i].toFloat64()) / N.toFloat64()
        }

        observed /= N.toFloat64()
        expected /= N.toFloat64()

        if (abs(1.0 - expected) < 0.00001) {
            return 1.0
        }

        return (observed - expected) / (1.0 - expected)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Calculate p_j (proportion of all assignments to j-th category)
        var p = ArrayList<Float64>([])
