        var P = ArrayList<Float64>([])
        for (i in 0..N) {
            var sum = 0.0
            for (j in 0..k) {
                sum += testData[i][j].toFloat64() * (testData[i][j].toFloat64() - 1.0)
            }
            P.add(sum / (n.toFloat64() * (n.toFloat64() - 1.0)))
        }

        // Calculate P_bar (mean of P_i) and P_e (expected agreement by chance)
        var P_bar = 0.0
        for (pi in P) {
            P_bar += pi
        }
        P_bar /= N.toFloat64()

        var P_e = 0.0
        for (pj in p) {
