class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var sum = 0
        var total = 0
        var po = 0.0
        var pe = 0.0

        // Calculate total and diagonal sum
        for (i in 0..k) {
            for (j in 0..k) {
                total += testData[i][j]
                if (i == j) {
                    sum += testData[i][j]
                }
            }
        }

        // Calculate observed agreement (po) and expected agreement (pe)
        po = Float64(sum) / Float64(total)

        var row_sums = ArrayList<Int64>([])
        var col_sums = ArrayList<Int64>([])

        // Initialize sums
        for (i in 0..k) {
            row_sums.add(0)
            col_sums.add(0)
        }

        // Calculate row and column sums
        for (i in 0..k) {
            for (j in 0..k) {
                row_sums[i] += testData[i][j]
                col_sums[j] += testData[i][j]
            }
        }

        // Calculate pe
        for (i in 0..k) {
            pe += Float64(row_sums[i] * col_sums[i])
        }
        pe /= Float64(total * total)

        // Return Cohen's kappa
        return (po - pe) / (1 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var P = ArrayList<Float64>([])
        var sum_pj = 0.0
        var sum_Pi = 0.0

        // Initialize P array
        for (i in 0..N) {
            P.add(0.0)
        }

        // Calculate Pi values
        for (i in 0..N) {
            var sum_row = 0
            for (j in 0..k) {
                sum_row += testData[i][j]
            }
            var Pi = 0.0
            for (j in 0..k) {
                Pi += Float64(testData[i][j] * (testData[i][j] - 1))
            }
            Pi /= Float64(sum_row * (sum_row - 1))
            P[i] = Pi
            sum_Pi += Pi
        }

        // Calculate pj values
        var pj_list = ArrayList<Float64>([])
        for (j in 0..k) {
            pj_list.add(0.0)
        }

        for (j in 0..k) {
            var sum_col = 0
            for (i in 0..N) {
                sum_col += testData[i][j]
            }
            pj_list[j] = Float64(sum_col) / Float64(N * n)
            sum_pj += pj_list[j] * pj_list[j]
        }

        // Calculate Fleiss' kappa
        var P_bar = sum_Pi / Float64(N)
        var P_e = sum_pj

        return (P_bar - P_e) / (1 - P_e)
    }
}

