class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let n = testData[0].toArray().reduce(0, {acc, x => acc + x})
        var p0: Float64 = 0.0
        var sum_pe: Float64 = 0.0

        for i in 0..k {
            p0 += testData[i][i].toFloat64()
            let row_sum = testData[i].toArray().reduce(0, {acc, x => acc + x})
            let col_sum = testData.toArray().map({row => row[i]}).reduce(0, {acc, x => acc + x})
            sum_pe += row_sum.toFloat64() * col_sum.toFloat64()
        }

        p0 = p0 / n.toFloat64()
        let pe = sum_pe / (n.toFloat64() * n.toFloat64())
        if (abs(1.0 - pe) < 0.000001) {
            return 1.0
        }
        return (p0 - pe) / (1.0 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var pj = ArrayList<Float64>([])
        var sum_pj = 0.0
        var sum_pi = 0.0

        for j in 0..k {
            let col_sum = testData.toArray().map({row => row[j].toFloat64()}).reduce(0.0, {acc, x => acc + x})
            let p_j = col_sum / (N.toFloat64() * n.toFloat64())
            pj.add(p_j)
            sum_pj += p_j * p_j
        }

        for i in 0..N {
            var sum_row = 0.0
            var sum_row_sq = 0.0
            for j in 0..k {
                let x_ij = testData[i][j].toFloat64()
                sum_row += x_ij
                sum_row_sq += x_ij * x_ij
            }
            let p_i = (sum_row_sq - sum_row) / (sum_row * (sum_row - 1.0))
            sum_pi += p_i
        }

        let P = sum_pi / N.toFloat64()
        let Pbar_e = sum_pj
        if (abs(1.0 - Pbar_e) < 0.000001) {
            return 1.0
        }
        return (P - Pbar_e) / (1.0 - Pbar_e)
    }
}

