class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let total = testData.foldLeft(0, {acc: Int64, row: ArrayList<Int64> =>
            acc + row.foldLeft(0, {acc2, x => acc2 + x})
        })

        var po: Float64 = 0.0
        var pe: Float64 = 0.0

        // Calculate observed agreement (po)
        for (i in 0..testData.size) {
            let row = testData[i]
            po += row[i].toFloat64()
        }
        po /= total.toFloat64()

        // Calculate expected agreement (pe)
        var rowSums = ArrayList<Int64>()
        var colSums = ArrayList<Int64>()

        for (_ in 0..k) {
            rowSums.add(0)
            colSums.add(0)
        }

        for (i in 0..testData.size) {
            for (j in 0..testData[i].size) {
                rowSums[i] += testData[i][j]
                colSums[j] += testData[i][j]
            }
        }

        for (i in 0..k) {
            pe += rowSums[i].toFloat64() * colSums[i].toFloat64()
        }
        pe /= (total.toFloat64() * total.toFloat64())

        let kappa = if (abs(1.0 - pe) < 0.00001) {
            1.0
        } else {
            (po - pe) / (1.0 - pe)
        }

        return kappa
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var pj = ArrayList<Float64>()
        for (_ in 0..k) {
            pj.add(0.0)
        }

        // Calculate pj values
        for (i in 0..N) {
            for (j in 0..k) {
                pj[j] += testData[i][j].toFloat64()
            }
        }

        for (j in 0..k) {
            pj[j] /= (N.toFloat64() * n.toFloat64())
        }

        // Calculate Pi values
        var Pi = ArrayList<Float64>()
        for (i in 0..N) {
            var sum = 0.0
            var sumSq = 0.0
            for (j in 0..k) {
                sum += testData[i][j].toFloat64()
                sumSq += testData[i][j].toFloat64() * testData[i][j].toFloat64()
            }
            Pi.add((sumSq - sum) / (sum * (sum - 1.0)))
        }

        // Calculate Pbar and Pe
        let Pbar = Pi.foldLeft(0.0, {acc, x => acc + x}) / N.toFloat64()
        let Pe = pj.foldLeft(0.0, {acc, x => acc + x * x})

        let kappa = if (abs(1.0 - Pe) < 0.00001) {
            1.0
        } else {
            (Pbar - Pe) / (1.0 - Pe)
        }

        return kappa
    }
}

