class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let n = testData[0].reduce(0, {acc, x => acc + x})
        let po: Float64 = testData.enumerate().reduce(0.0, {acc, (i, row) =>
            acc + row[i].toFloat64()
        }) / n.toFloat64()

        let pe = testData.map({row => row.reduce(0, {acc, x => acc + x}).toFloat64()})
                .reduce(0.0, {acc, sumRow => acc + sumRow}) / (n * k).toFloat64()

        return (po - pe) / (1.0 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Calculate Pj: proportion of all assignments to j-th category
        let Pj = ArrayList<Float64>([])
        let sumCols = ArrayList<Int64>([])
        for j in 0..k {
            let colSum = testData.reduce(0, {acc, row => acc + row[j]})
            sumCols.add(colSum)
            Pj.add(colSum.toFloat64() / (N * n).toFloat64())
        }

        // Calculate Pi: extent to which raters agree for i-th subject
        let Pi = ArrayList<Float64>([])
        for i in 0..N {
            let numerator = testData[i].reduce(0, {acc, x => acc + x * (x - 1)}).toFloat64()
            Pi.add(numerator / (n * (n - 1)).toFloat64())
        }

        // Calculate Pbar (mean of Pi) and Pbar_e (mean of Pj squares)
        let Pbar = Pi.reduce(0.0, {acc, p => acc + p}) / N.toFloat64()
        let Pbar_e = Pj.reduce(0.0, {acc, pj => acc + pj * pj})

        return (Pbar - Pbar_e) / (1.0 - Pbar_e)
    }
}

