import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        var board = ArrayList<ArrayList<String>>([])
        let random = Random()

        for (i in 0..rows) {
            var row = ArrayList<String>([])
            for (j in 0..cols) {
                let icon = ICONS[random.next(ICONS.size)]
                row.add(icon, at: j)
            }
            board.add(row, at: i)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        if (pos1[0] < 0 || pos1[0] >= BOARD_SIZE[0] || pos1[1] < 0 || pos1[1] >= BOARD_SIZE[1]) {
            return false
        }
        if (pos2[0] < 0 || pos2[0] >= BOARD_SIZE[0] || pos2[1] < 0 || pos2[1] >= BOARD_SIZE[1]) {
            return false
        }
        if (pos1 == pos2) {
            return false
        }
        if (board[pos1[0]][pos1[1]] != board[pos2[0]][pos2[1]]) {
            return false
        }
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        var visited = ArrayList<(Int64, Int64)>([])
        var queue = ArrayList<(Int64, Int64)>([])

        queue.add(pos1, at: 0)
        visited.add(pos1, at: 0)

        while (queue.size > 0) {
            let current = queue.remove(at: 0)
            let (x, y) = current

            if (current == pos2) {
                return true
            }

            let neighbors = [(x+1, y), (x-1, y), (x, y+1), (x, y-1)]
            for (neighbor in neighbors) {
                let (nx, ny) = neighbor
                if (nx >= 0 && nx < BOARD_SIZE[0] && ny >= 0 && ny < BOARD_SIZE[1]) {
                    if (!contains(visited, neighbor) && (board[nx][ny] == " " || neighbor == pos2)) {
                        visited.add(neighbor, at: visited.size)
                        queue.add(neighbor, at: queue.size)
                    }
                }
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        board[pos1[0]][pos1[1]] = " "
        board[pos2[0]][pos2[1]] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (icon in row) {
                if (icon != " ") {
                    return false
                }
            }
        }
        return true
    }
}

