    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let board = ArrayList<ArrayList<String>>()
        let rng = Random()

        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                let random_idx = rng.nextInt(ICONS.size)
                row.add(ICONS[random_idx], at: j)
            }
            board.add(row, at: i)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        // Check positions are within bounds
        if (pos1[0] < 0 || pos1[0] >= BOARD_SIZE[0] || 
            pos1[1] < 0 || pos1[1] >= BOARD_SIZE[1] ||
            pos2[0] < 0 || pos2[0] >= BOARD_SIZE[0] || 
            pos2[1] < 0 || pos2[1] >= BOARD_SIZE[1]) {
            return false
        }

        // Check not same position
        if (pos1 == pos2) {
            return false
        }

        // Check same icon
        if (board[pos1[0]][pos1[1]] != board[pos2[0]][pos2[1]]) {
            return false
        }

        // Check path exists
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let visited = ArrayList<(Int64, Int64)>()
        return dfs(pos1, pos2, (-1, -1), visited)
    }

    private func dfs(current: (Int64, Int64), target: (Int64, Int64), 
                    from: (Int64, Int64), visited: ArrayList<(Int64, Int64)>): Bool {
        // Base case: reached target
        if (current == target) {
            return true
        }

        // Mark current position as visited
        visited.add(current, at: visited.size)

        // Get neighboring positions (up, down, left, right)
        let neighbors = [
            (current[0]-1, current[1]),
            (current[0]+1, current[1]),
            (current[0], current[1]-1),
            (current[0], current[1]+1)
        ]

        // Check each neighbor
        for (neighbor in neighbors) {
            // Skip out-of-bounds neighbors
            if (neighbor[0] < 0 || neighbor[0] >= BOARD_SIZE[0] ||
                neighbor[1] < 0 || neighbor[1] >= BOARD_SIZE[1]) {
                continue
            }

            // Skip the position we came from
            if (neighbor == from) {
                continue
            }

            // Skip already visited positions
            if (MahjongConnect.contains(visited, neighbor)) {
                continue
            }

            // Skip occupied positions that aren't the target
            if (board[neighbor[0]][neighbor[1]] != " " && neighbor != target) {
                continue
            }

            // Recursively check path
            if (dfs(neighbor, target, current, visited)) {
                return true
            }
        }

        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        board[pos1[0]][pos1[1]] = " "
        board[pos2[0]][pos2[1]] = " "
    }

    public func is_game_over(): Bool {
        for (i in 0..BOARD_SIZE[0]) {
            for (j in 0..BOARD_SIZE[1]) {
                if (board[i][j] != " ") {
                    return false
                }
            }
        }
        return true
    }
}

