class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if (center - diff < 0 || center + diff >= string.toRuneArray().size || 
            string.toRuneArray()[center - diff] != string.toRuneArray()[center + diff]) {
            return 0
        }
        return 1 + palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        let arr = this.input_string.toRuneArray()
        if (arr.size == 0) {
            return ""
        }

        var new_string_list = ArrayList<Rune>()
        for (element in arr) {
            new_string_list.add(element)
            new_string_list.add(r'|')
        }
        new_string_list.remove(new_string_list.size - 1)

        let new_string = String(new_string_list)
        let len = new_string.toRuneArray().size
        var max_pal_length = 0
        var center_index = 0

        for (i in 0..len) {
            let pal_length = palindromic_length(i, 1, new_string)
            if (pal_length > max_pal_length) {
                max_pal_length = pal_length
                center_index = i
            }
        }

        let start = (center_index - max_pal_length) / 2
        let end = (center_index + max_pal_length) / 2
        let result_arr = Array<Rune>(arr[start..end])

        return String(result_arr)
    }
}

