                max_len = diff
                best_center = i
            }
        }

        let start = best_center - max_len
        let end = best_center + max_len
        let palindrome = new_str.toRuneArray()
            .slice(start, end)
            .filter({r: Rune, i: Int64 => i % 2 != 0})
            .map({r: Rune => r.toString()})
            .reduce("", {a: String, b: String => a + b})

        return palindrome
    }
