        if ((center - diff) >= 0 && 
            (center + diff) < string.size && 
            string[(center - diff)] == string[(center + diff)]) {
            return palindromic_length(center, diff + 1, string)
        } else {
            return diff - 1
        }
    }

    public func palindromic_string(): String {
        let max_length = this.input_string.size
        if (max_length == 0) {
            return ""
        }

        let max_length_changed = 2 * max_length + 1
        let l = ArrayList<Int64>([])
        var current_center = 0
        var current_right = 0
        var max_pal_length = 0
        var max_pal_center = 0

        for (i in 0..max_length_changed) {
            l.add(0, at: i)

            if (current_right > i) {
                l[i] = min(l[2 * current_center - i], current_right - i)
            }

            let max_length_temp = palindromic_length(
                i, l[i] + 1, 
                this.input_string.toRuneArray().map({x => x.toString()}).join("|")
            )
            l[i] = max_length_temp

            if (i + l[i] > current_right) {
                current_center = i
                current_right = i + l[i]
            }

            if (l[i] > max_pal_length) {
                max_pal_length = l[i]
                max_pal_center = i
            }
        }

        let start = (max_pal_center - max_pal_length) / 2
        let end = start + max_pal_length
        return String(this.input_string.runes().skip(start).take(end - start).map({x => x.toString()}).join(""))
    }
