class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if (center + diff >= string.size || center - diff < 0) {
            return -1
        }

        let l = string[center - diff]
        let r = string[center + diff]

        if (l != r) {
            return -1
        }

        return palindromic_length(center, diff + 1, string) + 1
    }

    public func palindromic_string(): String {
        let processed_str = ArrayList<Rune>()

        // Preprocess the string with separators
        for (ch in this.input_string.runes()) {
            processed_str.add(r'|')
            processed_str.add(ch)
        }
        processed_str.add(r'|')

        let palindromic_lengths = ArrayList<Int64>([])
        for (_ in 0..processed_str.size) {
            palindromic_lengths.add(0)
        }

        var center = 0
        var right_bound = 0
        var max_len = 0
        var max_center = 0

        for (i in 0..processed_str.size) {
            let mirror = 2 * center - i

            if (i < right_bound) {
                palindromic_lengths[i] = min(right_bound - i, palindromic_lengths[mirror])
            }

            let curr_len = palindromic_length(i, palindromic_lengths[i] + 1, processed_str)

            if (curr_len > 0) {
                palindromic_lengths[i] = curr_len
            }

            if (i + palindromic_lengths[i] > right_bound) {
                center = i
                right_bound = i + palindromic_lengths[i]

                if (palindromic_lengths[i] > max_len) {
                    max_len = palindromic_lengths[i]
                    max_center = i
                }
            }
        }

        // Extract the longest palindrome
        let start_idx = (max_center - max_len) / 2
        let end_idx = (max_center + max_len) / 2

        return this.input_string[start_idx..end_idx]
    }
}

