            if (string.runes().nth((center - diff).toIntNative()) == string.runes().nth((center + diff).toIntNative())) {
                return 1 + palindromic_length(center, diff + 1, string)
            }
        }
        return 0
    }

    public func palindromic_string(): String {
        let max_length = this.input_string.size
        if (max_length == 0) {
            return ""
        }

        let new_string = Array<Rune>(this.input_string.runes()).join("|")
        let palindromic_lengths = ArrayList<Int64>([])

        for (i in 0..new_string.size.toInt64()) {
            palindromic_lengths.add(palindromic_length(i, 1, new_string))
        }

        let max_palindromic_length = palindromic_lengths.max().getOrThrow()
        let center_index = palindromic_lengths.index_of(max_palindromic_length).getOrThrow()

        let start_index = (center_index.toInt64() - max_palindromic_length) / 2
        let end_index = (center_index.toInt64() + max_palindromic_length) / 2

        return Array<Rune>(this.input_string.runes()).slice(start_index.toIntNative(), end_index.toIntNative()).join("")
    }
}

