        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if ((center - diff) >= 0 && (center + diff) < string.toRuneArray().size 
            && string.toRuneArray()[center - diff] == string.toRuneArray()[center + diff]) {
            return 1 + palindromic_length(center, diff + 1, string)
        } else {
            return 0
        }
    }

    public func palindromic_string(): String {
        let new_string = input_string.toRuneArray()
                                    .map({r: Rune => "${r}|"})
                                    .fold("", {a: String, b: String => a + b})
        let len = new_string.toRuneArray().size
        var max_len: Int64 = 0
        var max_center: Int64 = 0

        for (i in 0..len) {
            let current_len = palindromic_length(i, 1, new_string)
            if (current_len > max_len) {
                max_len = current_len
                max_center = i
            }
        }

        let start = max_center - max_len
        let end = max_center + max_len
        let result = new_string.toRuneArray()[start..end+1]
                              .filter({r: Rune => r != r'|'})
                              .map({r: Rune => "${r}"})
                              .fold("", {a: String, b: String => a + b})
        return result
    }
}

