    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()
        // Initialize empty map
        for (_ in 0..n) {
            let row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("0")
            }
            map.add(row)
        }

        // Place mines randomly
        let rand = Random()
        var mines_placed = 0
        while (mines_placed < k) {
            let x = rand.nextInt64(min: 0, max: n-1)
            let y = rand.nextInt64(min: 0, max: n-1)
            if (map[x][y] != "X") {
                map[x][y] = "X"
                mines_placed += 1

                // Update adjacent cells
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && map[nx][ny] != "X") {
                            let current_value = map[nx][ny].toInt64()
                            map[nx][ny] = "${current_value + 1}"
                        }
                    }
                }
            }
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            let row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (minesweeper_map[i][j] != "X" && map[i][j] == "-") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map[x][y] == "X") {
            return false
        }

        if (player_map[x][y] != "-") {
            return player_map
        }

        player_map[x][y] = minesweeper_map[x][y]

        // Reveal adjacent empty cells
        if (minesweeper_map[x][y] == "0") {
            for (dx in -1..2) {
                for (dy in -1..2) {
                    let nx = x + dx
                    let ny = y + dy
                    if (nx >= 0 && nx < n && ny >= 0 && ny < n && player_map[nx][ny] == "-") {
                        sweep(nx, ny)
                    }
                }
            }
        }

        if (check_won(player_map)) {
            return true
        }
        return player_map
    }
}

