import std.convert.Parsable

class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        var mine_positions = ArrayList<(Int64, Int64)>()

        // Initialize empty map
        for _ in 0..n {
            var row = ArrayList<String>()
            for _ in 0..n {
                row.add("0")
            }
            map.add(row)
        }

        // Place mines randomly
        let rand = Random()
        var mines_placed: Int64 = 0
        while (mines_placed < k) {
            let x = rand.nextInt64(0, n)
            let y = rand.nextInt64(0, n)
            if (map[x][y] != "X") {
                map[x][y] = "X"
                mine_positions.add((x, y))
                mines_placed += 1
            }
        }

        // Calculate numbers around mines
        for (x, y) in mine_positions {
            for i in max(0, x-1)..min(n, x+2) {
                for j in max(0, y-1)..min(n, y+2) {
                    if (map[i][j] != "X") {
                        let current = map[i][j].parseInt64().getOrThrow()
                        map[i][j] = "${current + 1}"
                    }
                }
            }
        }

        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for _ in 0..n {
            var row = ArrayList<String>()
            for _ in 0..n {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for i in 0..n {
            for j in 0..n {
                if (minesweeper_map[i][j] != "X" && map[i][j] == "-") {
                    return false
                }
                if (minesweeper_map[i][j] == "X" && map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map[x][y] == "X") {
            // Reveal all mines
            revealMines()
            return false
        }

        revealCell(x, y)

        if (check_won(player_map)) {
            return true
        }

        return player_map
    }

    private func revealCell(x: Int64, y: Int64): Unit {
        if (x < 0 || x >= n || y < 0 || y >= n || player_map[x][y] != "-") {
            return
        }

        player_map[x][y] = minesweeper_map[x][y]

        if (minesweeper_map[x][y] == "0") {
            for i in max(0, x-1)..min(n, x+2) {
                for j in max(0, y-1)..min(n, y+2) {
                    if (!(i == x && j == y)) {
                        revealCell(i, j)
                    }
                }
            }
        }
    }

    private func revealMines(): Unit {
        for i in 0..n {
            for j in 0..n {
                if (minesweeper_map[i][j] == "X") {
                    player_map[i][j] = "X"
                }
            }
        }
    }

    private func max(a: Int64, b: Int64): Int64 {
        return if (a > b) { a } else { b }
    }

    private func min(a: Int64, b: Int64): Int64 {
        return if (a < b) { a } else { b }
    }
}

