class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let mine_positions = HashSet<(Int64, Int64)>()
        let random = Random()

        while (mine_positions.size < k) {
            let x = random.next(n)
            let y = random.next(n)
            mine_positions.add((x, y))
        }

        let mines = HashMap<(Int64, Int64), Bool>()
        for pos in mine_positions {
            mines.add(pos, true)
        }

        let board = ArrayList<ArrayList<String>>()
        for i in 0..n {
            let row = ArrayList<String>()
            for j in 0..n {
                if (mines.contains((i, j))) {
                    row.add("X")
                } else {
                    let mut count: Int64 = 0
                    for di in -1..2 {
                        for dj in -1..2 {
                            let ni = i + di
                            let nj = j + dj
                            if (di != 0 || dj != 0) && ni >= 0 && ni < n && nj >= 0 && nj < n && mines.contains((ni, nj)) {
                                count = count + 1
                            }
                        }
                    }
                    row.add(count.toString())
                }
            }
            board.add(row)
        }
        return board
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let board = ArrayList<ArrayList<String>>()
        for _ in 0..n {
            let row = ArrayList<String>()
            for _ in 0..n {
                row.add("-")
            }
            board.add(row)
        }
        return board
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        let mut uncovered = 0
        for i in 0..n {
            for j in 0..n {
                if map[i][j] != "-" && minesweeper_map[i][j] != "X" {
                    uncovered = uncovered + 1
                }
            }
        }
        return uncovered == n * n - k
    }

    public func sweep(x: Int64, y: Int64): Any {
        if minesweeper_map[x][y] == "X" {
            player_map[x][y] = "X"
            return false
        }

        let mut queue = ArrayList<(Int64, Int64)>()
        queue.add((x, y))

        while queue.size > 0 {
            let (i, j) = queue.remove(at: 0)
            if player_map[i][j] != "-" {
                continue
            }

            player_map[i][j] = minesweeper_map[i][j]
            score = score + 1

            if minesweeper_map[i][j] == "0" {
                for di in -1..2 {
                    for dj in -1..2 {
                        let ni = i + di
                        let nj = j + dj
                        if ni >= 0 && ni < n && nj >= 0 && nj < n && player_map[ni][nj] == "-" {
                            queue.add((ni, nj))
                        }
                    }
                }
            }
        }

        if check_won(player_map) {
            return true
        }
        return player_map
    }
}

