        while (mine_positions.size < k) {
            let x = Random.nextInt64(min: 0, max: n)
            let y = Random.nextInt64(min: 0, max: n)
            mine_positions.add((x, y))
        }

        var map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                if (mine_positions.contains((i, j))) {
                    row.add("X")
                } else {
                    var count: Int64 = 0
                    for (di in -1..2) {
                        for (dj in -1..2) {
                            if (di == 0 && dj == 0) {
                                continue
                            }
                            let ni = i + di
                            let nj = j + dj
                            if (ni >= 0 && ni < n && nj >= 0 && nj < n && mine_positions.contains((ni, nj))) {
                                count = count + 1
                            }
                        }
                    }
                    row.add(String(count))
                }
            }
            map.add(row)
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            var row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..this.n) {
            for (j in 0..this.n) {
                if (map[i][j] == "-" && this.minesweeper_map[i][j] != "X") {
                    return false
                }
