        let board = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            let row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("0")
            }
            board.add(row)
        }

        // Place mines randomly
        var mines_placed = 0
        while (mines_placed < k) {
            let x = Random.nextInt64(0, n)
            let y = Random.nextInt64(0, n)
            if (board[x][y] != "X") {
                board[x][y] = "X"
                mines_placed = mines_placed + 1

                // Update adjacent numbers
                for (i in -1..2) {
                    for (j in -1..2) {
                        let nx = x + i
                        let ny = y + j
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && board[nx][ny] != "X") {
                            let current = Parsable.parseInt64(board[nx][ny])
                            board[nx][ny] = (current + 1).toString()
                        }
                    }
                }
            }
        }
        return board
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
