        this.k = k
        this.minesweeper_map = MinesweeperGame.generate_mine_sweeper_map(n, k)
        this.player_map = MinesweeperGame.generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let empty_map = ArrayList<ArrayList<String>>()
        // Initialize empty map
        for (_ in 0..n) {
            let row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("0")
            }
            empty_map.add(row)
        }

        // Place mines randomly
        let random = Random()
        var mines_placed = 0
        while (mines_placed < k) {
            let x = random.nextInt64(n)
            let y = random.nextInt64(n)
            if (empty_map[x][y] != "X") {
                empty_map[x][y] = "X"
                mines_placed = mines_placed + 1
            }
        }

        // Calculate numbers
        for (i in 0..n) {
            for (j in 0..n) {
                if (empty_map[i][j] == "X") {
                    continue
                }
                var count = 0
                // Check all 8 neighbors
                for (di in -1..2) {
                    for (dj in -1..2) {
                        if (di == 0 && dj == 0) {
                            continue
                        }
                        let ni = i + di
                        let nj = j + dj
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n && empty_map[ni][nj] == "X") {
                            count = count + 1
                        }
                    }
                }
                if (count > 0) {
                    empty_map[i][j] = count.toString()
                }
            }
        }

        return empty_map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            let row = ArrayList<String>()
            for (_ in 0..n) {
