                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        // Check bounds
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return player_map
        }

        // Check if already revealed
        if (player_map[x][y] != "-") {
            return player_map
        }

        // Hit mine
        if (minesweeper_map[x][y] == "X") {
            // Reveal all mines
            for (i in 0..n) {
                for (j in 0..n) {
                    if (minesweeper_map[i][j] == "X") {
                        player_map[i][j] = "X"
                    }
                }
            }
            return false
        }

        // Reveal cell
        player_map[x][y] = minesweeper_map[x][y]

        // If 0, reveal neighbors
        if (minesweeper_map[x][y] == "0") {
            for (di in -1..2) {
                for (dj in -1..2) {
