import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some<String>(value) => this.format_string(value)
            case None<String> => "ZERO ONLY"
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let integer_part = parts[0]
        let decimal_part = if (parts.size > 1) { parts[1] } else { "" }

        let integer_words = this.parse_integer(integer_part)
        let decimal_words = if (decimal_part != "") {
            " AND ${this.parse_decimal(decimal_part)}"
        } else {
            ""
        }

        "${integer_words}${decimal_words} ONLY"
    }

    private func parse_integer(s: String): String {
        if (s == "0") { return "ZERO" }

        let s_padded = "0".repeat(3 - (s.size % 3)) + s
        let chunks = []
        for (i in 0..s_padded.size:3) {
            chunks.add(s_padded[i..i+3], at: 0)
        }

        let words = []
        for (i in 0..chunks.size) {
            let chunk_words = this.trans_three(chunks[i])
            if (chunk_words != "") {
                words.add("${chunk_words} ${this.parse_more(i)}", at: 0)
            }
        }

        words.join(" ").trim()
    }

    private func parse_decimal(s: String): String {
        let words = []
        for (c in s.toRuneArray()) {
            let digit = c.toString().toInt64() ?? 0
            words.add(this.NUMBER[digit])
        }
        "CENTS ${words.join(" ")}"
    }

    public func trans_two(s: String): String {
        let n = s.toInt64() ?? 0
        if (n == 0) { return "" }
        if (n < 10) { return this.NUMBER[n] }
        if (n < 20) { return this.NUMBER_TEEN[n - 10] }

        let tens = this.NUMBER_TEN[(n / 10) - 1]
        let units = if (n % 10 != 0) { this.NUMBER[n % 10] } else { "" }
        if (units == "") { tens } else { "${tens} ${units}" }
    }

    public func trans_three(s: String): String {
        let n = s.toInt64() ?? 0
        if (n == 0) { return "" }

        let hundreds = this.NUMBER[n / 100]
        let rest = if (hundreds != "") { 
            "HUNDRED AND ${this.trans_two((n % 100).toString())}" 
        } else { 
            this.trans_two((n % 100).toString())
        }

        if (hundreds == "") { rest } else { "${hundreds} ${rest}" }
    }

    public func parse_more(i: Int64): String {
        if (i < this.NUMBER_MORE.size) {
            this.NUMBER_MORE[i]
        } else {
            ""
        }
    }
}

import std.convert.Parsable
