        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case None<String> => "ZERO ONLY"
            case Some<String>(s) => this.format_string(s)
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let integer_part = parts[0]
        let decimal_part = if (parts.size > 1) { parts[1] } else { "" }

        let integer_words = this.format_integer(integer_part)
        let decimal_words = if (decimal_part != "") {
            " AND " + this.format_decimal(decimal_part)
        } else {
            ""
        }

        integer_words + decimal_words + " ONLY"
    }

    public func trans_two(s: String): String {
        let num = s.toInt64().getOrThrow()
        if (num < 10) {
            this.NUMBER[num]
        } else if (num < 20) {
            this.NUMBER_TEEN[num - 10]
        } else {
            let tens = num / 10
            let units = num % 10
            if (units == 0) {
                this.NUMBER_TEN[tens - 1]
            } else {
                this.NUMBER_TEN[tens - 1] + " " + this.NUMBER[units]
            }
        }
    }

    public func trans_three(s: String): String {
        let num = s.toInt64().getOrThrow()
        let hundreds = num / 100
        let remainder = num % 100

        if (hundreds == 0) {
            this.trans_two(remainder.toString())
        } else {
            let hundred_part = this.NUMBER[hundreds] + " HUNDRED"
            if (remainder == 0) {
                hundred_part
            } else {
                hundred_part + " AND " + this.trans_two(remainder.toString())
            }
        }
    }

    public func parse_more(i: Int64): String {
        if (i < this.NUMBER_MORE.size) {
            this.NUMBER_MORE[i]
        } else {
            ""
        }
    }

    private func format_integer(s: String): String {
        let num = s.toInt64().getOrThrow()
        if (num == 0) {
            return "ZERO"
        }

        let chunks = ArrayList<String>()
        let s_padded = s.padStart(s.size + (3 - s.size % 3) % 3, '0')

        for (i in 0..s_padded.size / 3) {
            let start = i * 3
            let chunk_str = s_padded[start..start + 3]
            chunks.add(chunk_str)
        }

        let words = ArrayList<String>()
        for (i in 0..chunks.size) {
            let chunk = chunks[chunks.size - 1 - i]
            let chunk_num = chunk.toInt64().getOrThrow()
            if (chunk_num != 0) {
                let chunk_words = this.trans_three(chunk)
                let magnitude = this.parse_more(i)
                words.add(chunk_words + " " + magnitude)
            }
        }

        words.reverse()
        words.join(" ").trim()
    }

    private func format_decimal(s: String): String {
        if (s.size == 1) {
            this.trans_two(s + "0") + " CENTS"
        } else {
            this.trans_two(s[0..2]) + " CENTS"
        }
    }
}

