                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case None<String> => "ZERO ONLY"
            case Some<String>(value) => {
                this.format_string(value)
            }
        }
    }

    public func format_string(x: String): String {
        var num: Int64 = 0
        try {
            num = x.parseInt()
        } catch (e) {
            return "ZERO ONLY"
        }

        if (num == 0) {
            return "ZERO ONLY"
        }

        let segments = ArrayList<String>()
        var remaining = num
        var segmentIndex = 0

        while (remaining > 0) {
            let segment = remaining % 1000
            remaining = remaining / 1000

            if (segment > 0) {
                let words = this.trans_three(segment.toString())
                let magnitude = this.parse_more(segmentIndex)
                let segmentWords = "${words} ${magnitude}".trim()
                segments.add(segmentWords, at: 0)
            }

            segmentIndex = segmentIndex + 1
        }

        let result = segments.join(" ")
        "${result} ONLY".trim()
    }

    public func trans_two(s: String): String {
        let num = s.parseInt()
        if (num < 10) {
            this.NUMBER[num.toInt()]
        } else if (num < 20) {
            this.NUMBER_TEEN[(num - 10).toInt()]
        } else {
            let tens = (num / 10).toInt()
            let units = (num % 10).toInt()
            if (units == 0) {
                this.NUMBER_TEN[tens - 1]
            } else {
                "${this.NUMBER_TEN[tens - 1]} ${this.NUMBER[units]}"
            }
        }
    }

    public func trans_threeophers s: String): String {
        let num = s.parseInt()
        let hundreds = (num / 100).toInt()
        let remainder = num % 100

        var result = ""
        if (hundreds > 0) {
            result = "${this.NUMBER[hundreds]} HUNDRED"
        }

        if (remainder > 0) {
            if (!result.isEmpty) {
                result = "${result} AND "
            }
            result = "${result}${this.trans_two(remainder.toString())}"
        }

        result
    }

    public func parse_more(i: Int64): String {
        if (i >= 0 && i < this.NUMBER_MORE.size) {
            this.NUMBER_MORE[i.toInt()]
        } else {
            ""
        }
    }
}

