        let numStr = x.trim()
        if (numStr == "") {
            return ""
        }

        let parts = numStr.split(".")
        let integerPart = parts[0]
        let decimalPart = if (parts.size > 1) { parts[1] } else { "" }

        let integerWords = this.convert_integer(integerPart)
        let decimalWords = if (decimalPart != "") {
            " POINT " + this.convert_decimal(decimalPart)
        } else {
            ""
        }

        if (integerWords == "" && decimalWords == "") {
            ""
        } else {
            integerWords + decimalWords + " ONLY"
        }
