    private func convert_integer(s: String): String {
        let num = s.replace(",", "").replace(" ", "")
        if (num == "0") {
            return "ZERO"
        }

        let chunks = ArrayList<String>()
        var i = num.size
        while (i > 0) {
            let start = if (i - 3 >= 0) { i - 3 } else { 0 }
            chunks.add(num[start..i], at: 0)
            i -= 3
        }

        let words = ArrayList<String>()
        for (idx, chunk) in chunks.enumerate() {
            let chunkWords = this.trans_three(chunk)
            if (chunkWords != "") {
                words.add(chunkWords)
                let suffix = this.parse_more(chunks.size - idx - 1)
                if (suffix != "") {
                    words.add(suffix)
                }
            }
        }

        words.join(" ")
    }

