        let hundreds = num / 100
        let remainder = num % 100

        let hundredsPart = if (hundreds > 0) { this.NUMBER[hundreds] + " HUNDRED" } else { "" }
        let remainderPart = if (remainder > 0) { this.trans_two(remainder.toString()) } else { "" }

