        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some<String>(s) => this.format_string(s)
            case None<String> => "ZERO ONLY"
        }
    }

    public func format_string(x: String): String {
        let numStr = x.trim()
        let n = numStr.size
        let result = if (n == 0) {
            ""
        } else if (n == 1) {
            this.NUMBER[numStr[0].toString().toInt64().getOrThrow()]
        } else if (n == 2) {
            this.trans_two(numStr)
        } else if (n == 3) {
            this.trans_three(numStr)
        } else {
            var parts = ArrayList<String>()
            let groupCount = (n + 2) / 3
            var remaining = n
            for (i in 0..groupCount) {
                let start = if (remaining <= 3) { 0 } else { remaining - 3 }
                let len = if (remaining <= 3) { remaining } else { 3 }
                let part = numStr.slice(start, start + len)
                let str = if (len == 1) {
                    this.NUMBER[part[0].toString().toInt64().getOrThrow()]
                } else if (len == 2) {
                    this.trans_two(part)
                } else {
                    this.trans_three(part)
                }
                if (str != "") {
                    let suffix = this.parse_more(i)
                    parts.add(str + (suffix != "" ? " ${suffix}" : ""), at: 0)
                }
                remaining = remaining - 3
            }
            parts.join(" ")
        }
