        for (i, chunk) in chunks.enumerate() {
            let chunk_words = this.trans_three(chunk)
            if (chunk_words != "") {
                result = chunk_words + " " + this.parse_more(i) + " " + result
            }
        }
        result.trim()
    }

    private func format_decimal(s: String): String {
        if (s.size == 1) {
            return this.trans_two(s + "0") + " CENTS"
        } else {
            return this.trans_two(s) + " CENTS"
        }
    }

    private func split_into_chunks(s: String): Array<String> {
        var chunks = ArrayList<String>()
        var i = s.size
        while (i > 0) {
            let start = max(i - 3, 0)
            chunks.add(s.slice(start, i), at: 0)
            i = start
        }
        chunks.toArray()
    }

