import std.collection.ArrayList

class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                let row = map[i]
                for (j in 0..row.size) {
                    let cell = row[j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (cell == "G") {
                        this.targets.add([i, j])
                        this.target_count = this.target_count + 1
                    } else if (cell == "X") {
                        this.boxes.add([i, j])
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var boxes_on_targets = 0
        for (box in boxes) {
            let [row, col] = box
            for (target in targets) {
                if (target[0] == row && target[1] == col) {
                    boxes_on_targets = boxes_on_targets + 1
                    break
                }
            }
        }
        this.is_game_over = boxes_on_targets == this.target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let dir_map = HashMap<String, (Int64, Int64)>([
            ("w", (-1, 0)),
            ("s", (1, 0)),
            ("a", (0, -1)),
            ("d", (0, 1))
        ])

        let (dr, dc) = dir_map.get(direction).getOrThrow()
        let new_row = this.player_row + dr
        let new_col = this.player_col + dc

        // Check wall
        if (this.map[new_row][new_col] == "#") {
            return false
        }

        // Check if moving to box
        var box_index = -1
        for (i in 0..boxes.size) {
