        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..this.map.size) {
                for (j in 0..this.map[i].size) {
                    let cell = this.map[i][j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (cell == "G") {
                        this.targets.add([i, j])
                        this.target_count = this.target_count + 1
                    } else if (cell == "X") {
                        this.boxes.add([i, j])
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var box_count = 0
        for (box in this.boxes) {
            for (target in this.targets) {
                if (box[0] == target[0] && box[1] == target[1]) {
                    box_count = box_count + 1
                }
            }
        }
        this.is_game_over = box_count == this.target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_row = this.player_row
        var new_col = this.player_col

        if (direction == "w") {
            new_row = new_row - 1
        } else if (direction == "s") {
            new_row = new_row + 1
        } else if (direction == "a") {
            new_col = new_col - 1
        } else if (direction == "d") {
            new_col = new_col + 1
        }

        // Check wall collision
        if (this.map[new_row][new_col] == "#") {
            return false
        }

        // Check box collision
        var box_moved = false
        var box_index = -1
        for (i in 0..this.boxes.size) {
            let box = this.boxes[i]
            if (box[0] == new_row && box[1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            // Calculate new box position
            let box_row = new_row + (new_row - this.player_row)
            let box_col = new_col + (new_col - this.player_col)

            // Check if new box position is valid
            if (this.map[box_row][box_col] == "#") {
                return false
            }

            // Check if new box position collides with another box
            for (box in this.boxes) {
                if (box[0] == box_row && box[1] == box_col) {
                    return false
                }
            }

            // Move the box
            this.boxes[box_index] = [box_row, box_col]
            box_moved = true
        }

        // Update player position
        this.player_row = new_row
        this.player_col = new_col

        return this.check_win()
    }
