        var new_row = this.player_row
        var new_col = this.player_col

        match (direction) {
            case "w" => new_row = new_row - 1
            case "s" => new_row = new_row + 1
            case "a" => new_col = new_col - 1
            case "d" => new_col = new_col + 1
            case _ => return false
        }

        if (this.map[new_row][new_col] == "#") {
            return false
        }

        var box_index = -1
        for (i in 0..this.boxes.size) {
            if (this.boxes[i][0] == new_row && this.boxes[i][1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index >= 0) {
