            case "w" => new_row = new_row - 1
            case "s" => new_row = new_row + 1
            case "a" => new_col = new_col - 1
            case "d" => new_col = new_col + 1
            case _ => {}
        }

        if (new_row < 0 || new_row >= this.map.size || new_col < 0 || new_col >= this.map[new_row].size) {
            return false
        }

        let next_cell = this.map[new_row][new_col]
        if (next_cell == "#") {
