    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions[0]
        let new_x = head[0] + direction[0] * this.BLOCK_SIZE
        let new_y = head[1] + direction[1] * this.BLOCK_SIZE
        let new_head = ArrayList<Int64>([new_x, new_y])

        // Check if new head position equals food position
        if (new_head[0] == this.food_position[0] && new_head[1] == this.food_position[1]) {
            this.eat_food()
        }
        // Check if snake hits itself
        else if (this.check_collision(new_head)) {
            this.reset()
        } 
        else {
            // Move normally
            this.positions.add(new_head, at: 0)
            if (this.positions.size > this.length) {
                this.positions.remove(at: this.positions.size - 1)
            }
        }
    }

    private func check_collision(position: ArrayList<Int64>): Bool {
        for p in this.positions {
            if (p[0] == position[0] && p[1] == position[1]) {
                return true
            }
        }
        return false
    }

    public func random_food_position(): Unit {
        let rand = Random()
        var new_pos: ArrayList<Int64>

        while (true) {
            let x = rand.nextInt(0, this.SCREEN_WIDTH / this.BLOCK_SIZE) * this.BLOCK_SIZE
            let y = rand.nextInt(0, this.SCREEN_HEIGHT / this.BLOCK_SIZE) * this.BLOCK_SIZE
            new_pos = ArrayList<Int64>([x, y])

            if (!this.check_collision(new_pos)) {
                break
            }
        }

        this.food_position = new_pos
    }

    public func reset(): Unit {
        this.length = 1
        this.score = 0
        this.positions = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])
        ])
        this.random_food_position()
    }

