    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        /*
        Split sentences that end with . or ? followed by space,
        excluding cases like Mr.
        */
        let pattern = Regex("(?<!\\w\\.\\w.)(?<![A-Z][a-z]\\.)(?<=\\.|\\?)\\s")
        let sentences = ArrayList<String>()
        let parts = sentences_string.split(pattern)
        for part in parts {
            sentences.add(part)
        }
        return sentences
    }

    public func count_words(sentence: String): Int64 {
        /*
        Count words (alphabetic sequences separated by spaces)
        */
        let words = sentence.split(Regex("\\s+"))
        var count: Int64 = 0
        for word in words {
            if word.matches(Regex("[a-zA-Z]+")) {
                count += 1
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        /*
        Find the maximum word count among all sentences
        */
        let sentences = this.split_sentences(sentences_string)
        var max_count: Int64 = 0
        for sentence in sentences {
            let current_count = this.count_words(sentence)
            if (current_count > max_count) {
                max_count = current_count
            }
        }
        return max_count
    }
}

