            case Some(f) => f.join(", ")
            case _ => "*"
        }
        let where_clause = match (condition) {
            case Some(c) => " WHERE " + c
            case _ => ""
        }
        return "SELECT ${fields_str} FROM ${this.table_name}${where_clause};"
    }

    public func insert(data: HashMap<String, String>): String {
