import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        let sorted = sort(data.copy())
        let n = sorted.size
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        }
        return Float64(sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        let modes = ArrayList<Int64>()
        var maxCount = 0

        for (num in data) {
            freq[num] = (freq.get(num) ?? 0) + 1
            if (freq[num] > maxCount) {
                maxCount = freq[num]
            }
        }

        for (entry in freq) {
            if (entry.value == maxCount) {
                modes.add(entry.key)
            }
        }

        return sort(modes)
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>()
        }

        let xMean = mean(x).getOrThrow()
        let yMean = mean(y).getOrThrow()

        var numerator = 0.0
        var xDenominator = 0.0
        var yDenominator = 0.0

        for (i in 0..x.size) {
            let xDiff = Float64(x[i]) - xMean
            let yDiff = Float64(y[i]) - yMean
            numerator += xDiff * yDiff
            xDenominator += xDiff * xDiff
            yDenominator += yDiff * yDiff
        }

        if (xDenominator == 0.0 || yDenominator == 0.0) {
            return None<Float64>()
        }

        return Some<Float64>(numerator / sqrt(xDenominator * yDenominator))
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }
        var sum = 0.0
        for (num in data) {
            sum += Float64(num)
        }
        return Some<Float64>(sum / Float64(data.size))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>()

        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                row.add(correlation(data[i], data[j]).getOrElse(0.0))
            }
            matrix.add(row)
        }

        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        if (m is None<Float64>) {
            return None<Float64>()
        }
        let meanValue = m.getOrThrow()
        var sumSq = 0.0

        for (num in data) {
            let diff = Float64(num) - meanValue
            sumSq += diff * diff
        }

        return Some<Float64>(sqrt(sumSq / Float64(data.size)))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let sd = standard_deviation(data)
        let m = mean(data)
        if (sd is None<Float64> || m is None<Float64>) {
            return None<ArrayList<Float64>>()
        }

        let stdDev = sd.getOrThrow()
        if (stdDev == 0.0) {
            return None<ArrayList<Float64>>()
        }

        let meanValue = m.getOrThrow()
        let zScores = ArrayList<Float64>()

        for (num in data) {
            zScores.add((Float64(num) - meanValue) / stdDev)
        }

        return Some<ArrayList<Float64>>(zScores)
    }
}

