            return 0.0
        }
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        if (sorted.size % 2 == 1) {
            return sorted[sorted.size / 2].toFloat64()
        } else {
            let mid = sorted.size / 2
            return (sorted[mid - 1] + sorted[mid]).toFloat64() / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let frequency = HashMap<Int64, Int64>()
        for (num in data) {
            frequency.add(num, (frequency.get(num) ?? 0) + 1)
        }

        let maxFrequency = frequency.values().reduce(0, {acc, x => if (x > acc) { x } else { acc }})
        let modes = ArrayList<Int64>()
        for (entry in frequency.entries()) {
            if (entry[1] == maxFrequency) {
                modes.add(entry[0])
            }
        }
        sort(modes)
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>()
        }

        let meanX = mean(x).getOrThrow()
        let meanY = mean(y).getOrThrow()

        var numerator = 0.0
        var denominatorX = 0.0
        var denominatorY = 0.0

        for (i in 0..x.size) {
            let xDiff = x[i].toFloat64() - meanX
            let yDiff = y[i].toFloat64() - meanY
            numerator += xDiff * yDiff
            denominatorX += xDiff * xDiff
            denominatorY += yDiff * yDiff
        }

        if (denominatorX == 0.0 || denominatorY == 0.0) {
            return None<Float64>()
        }

        return Some<Float64>(numerator / sqrt(denominatorX * denominatorY))
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }
        let sum = data.reduce(0, {acc, x => acc + x})
        return Some<Float64>(sum.toFloat64() / data.size.toFloat64())
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>()
        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                let corr = correlation(data[i], data[j])
                row.add(corr ?? 0.0)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        if (m.isNone() || data.size < 2) {
            return None<Float64>()
        }
        let avg = m.getOrThrow()
        let sumSq = data.reduce(0.0, {acc, x => acc + (x.toFloat64() - avg).pow(2)})
        return Some<Float64>(sqrt(sumSq / (data.size - 1).toFloat64()))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let avg = mean(data)
        let std = standard_deviation(data)
        if (avg.isNone() || std.isNone() || std.getOrThrow() == 0.0) {
            return None<ArrayList<Float64>>()
        }

        let scores = ArrayList<Float64>()
        let sd = std.getOrThrow()
        let meanVal = avg.getOrThrow()

        for (num in data) {
            scores.add((num.toFloat64() - meanVal) / sd)
        }

        return Some<ArrayList<Float64>>(scores)
    }
}

