        let frequency = HashMap<Int64, Int64>()
        let maxFreq = ArrayList<Int64>()
        var currentMax = 0

        for (num in data) {
            let count = frequency.get(num) ?? 0 + 1
            frequency.add(num, count)

            if (count > currentMax) {
                currentMax = count
                maxFreq.clear()
                maxFreq.add(num)
            } else if (count == currentMax) {
                maxFreq.add(num)
            }
        }

        return maxFreq
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>()
        }

        let n = x.size.toFloat64()
        let sumX = x.reduce(0, {a, b => a + b}).toFloat64()
        let sumY = y.reduce(0, {a, b => a + b}).toFloat64()
        let sumXY = (x.zip(y)).reduce(0.0, {a, b => a + (b[0].toFloat64() * b[1].toFloat64())})
        let sumX2 = x.reduce(0.0, {a, b => a + b.toFloat64().pow(2)})
        let sumY2 = y.reduce(0.0, {a, b => a + b.toFloat64().pow(2)})

        let numerator = sumXY - (sumX * sumY / n)
        let denominator = sqrt((sumX2 - sumX.pow(2) / n) * (sumY2 - sumY.pow(2) / n))

        if (denominator == 0.0) {
            return Some<Float64>(0.0)
        }

        return Some<Float64>(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }

        let sum = data.reduce(0, {a, b => a + b})
