            let row = ArrayList<Float64>()
            for (j in 0..data.size) {
                let corr = correlation(data[i], data[j]) ?? 0.0
                row.add(corr)
            }
            matrix.add(row)
        }

        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        if (m is None<Float64>) {
            return None<Float64>()
        }

        let meanVal = m.getOrThrow()
        let sumSq = data.reduce(0.0, {a, b => a + (b.toFloat64() - meanVal).pow(2)})
        let variance = sumSq / data.size.toFloat64()

        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let sd = standard_deviation(data)

        if (m is None<Float64> || sd is None<Float64>) {
            return None<ArrayList<Float64>>()
