        if (stdDev == 0.0) {
            return None<ArrayList<Float64>>()
        }

        let zScores = ArrayList<Float64>()
        for (num in data) {
            zScores.add((num.toFloat64() - meanVal) / stdDev)
        }

        return Some<ArrayList<Float64>>(zScores)
    }
