        let counts = HashMap<Int64, Int64>()
        let result = ArrayList<Int64>()
        var maxCount = 0

        for (num in data) {
            let count = counts.get(num) ?? 0 + 1
            counts.add(num, count)
            if (count > maxCount) {
                maxCount = count
                result.clear()
                result.add(num)
            } else if (count == maxCount) {
                result.add(num)
            }
        }
        return result
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>()
        }

        let meanX = mean(x).getOrThrow()
        let meanY = mean(y).getOrThrow()
        var numerator = 0.0
        var denomX = 0.0
        var denomY = 0.0

        for (i in 0..x.size) {
            let diffX = x[i].toFloat64() - meanX
            let diffY = y[i].toFloat64() - meanY
            numerator += diffX * diffY
            denomX += diffX * diffX
            denomY += diffY * diffY
        }

        if (denomX == 0.0 || denomY == 0.0) {
            return Some<Float64>(0.0)
        }
        return Some<Float64>(numerator / sqrt(denomX * denomY))
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }
        var sum = 0.0
        for (num in data) {
