            for (j in 0..n) {
                let corr = correlation(data[i], data[j]).getOrThrow()
                row.add(corr)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanRes = mean(data)
        if (meanRes is None<Float64>) {
            return None<Float64>()
        }
        let m = meanRes.getOrThrow()
        var sumSq = 0.0

        for (num in data) {
            let diff = num.toFloat64() - m
            sumSq += diff * diff
        }

        return Some<Float64>(sqrt(sumSq / data.size.toFloat64()))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
