        let m = meanRes.getOrThrow()
        let std = stdDevRes.getOrThrow()
        let result = ArrayList<Float64>()

        for (num in data) {
            result.add((num.toFloat64() - m) / std)
        }

        return Some<ArrayList<Float64>>(result)
    }
}

