        let sumX = x.reduce(0, {acc, val => acc + val}).toFloat64()
        let sumY = y.reduce(0, {acc, val => acc + val}).toFloat64()
        let sumXY = (0..x.size).reduce(0.0, {acc, i => acc + x[i].toFloat64() * y[i].toFloat64()})
        let sumX2 = x.reduce(0.0, {acc, val => acc + val.toFloat64().pow(2)})
        let sumY2 = y.reduce(0.0, {acc, val => acc + val.toFloat64().pow(2)})

        let numerator = sumXY - (sumX * sumY) / n
        let denominator = sqrt((sumX2 - sumX.pow(2) / n) * (sumY2 - sumY.pow(2) / n))

        if (denominator == 0.0) {
            return None<Float64>()
        }
        return Some<Float64>(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
