        let sumY2 = y.map({v => v.toFloat64() * v.toFloat64()}).reduce({acc, v => acc + v})

        let numerator = sumXY - (sumX * sumY) / n
        let denominator = sqrt((sumX2 - (sumX * sumX) / n) * (sumY2 - (sumY * sumY) / n))

        if (denominator == 0.0) {
            return None<Float64>
        }

        return Some<Float64>(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
