        }
        let m = mean_val.getOrThrow()
        let sum_sq = data.reduce(0.0, {acc: Float64, x: Int64 => 
            let diff = x.toFloat64() - m
            acc + diff * diff
        })
        return Some<Float64>(sqrt(sum_sq / data.size.toFloat64()))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_val = mean(data)
        let std_dev_val = standard_deviation(data)
        if (mean_val is None<Float64> || std_dev_val is None<Float64> || std_dev_val.getOrThrow() == 0.0) {
            return None<ArrayList<Float64>>()
        }
