class TicTacToe {
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(" ")
            }
            this.board.add(row)
        }
        this.current_player = "X"
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row >= this.board.size || col >= this.board[0].size || this.board[row][col] != " ") {
            return false
        }
        this.board[row][col] = this.current_player
        this.current_player = if (this.current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        let size = this.board.size

        // Check rows
        for (row in 0..size) {
            let first = this.board[row][0]
            if (first != " ") {
                var win = true
                for (col in 1..size) {
                    if (this.board[row][col] != first) {
                        win = false
                        break
                    }
                }
                if (win) { return Some<String>(first) }
            }
        }

        // Check columns
        for (col in 0..size) {
            let first = this.board[0][col]
            if (first != " ") {
                var win = true
                for (row in 1..size) {
                    if (this.board[row][col] != first) {
                        win = false
                        break
                    }
                }
                if (win) { return Some<String>(first) }
            }
        }

        // Check diagonals
        let first_diag = this.board[0][0]
        if (first_diag != " ") {
            var win = true
            for (i in 1..size) {
                if (this.board[i][i] != first_diag) {
                    win = false
                    break
                }
            }
            if (win) { return Some<String>(first_diag) }
        }

        let second_diag = this.board[0][size-1]
        if (second_diag != " ") {
            var win = true
            for (i in 1..size) {
                if (this.board[i][size-1-i] != second_diag) {
                    win = false
                    break
                }
            }
            if (win) { return Some<String>(second_diag) }
        }

        return None<String>
    }

    public func is_board_full(): Bool {
        for (row in 0..this.board.size) {
            for (col in 0..this.board[0].size) {
                if (this.board[row][col] == " ") {
                    return false
                }
            }
        }
        return true
    }
}

