        :param month: Int64
        :param day: Int64
        :param hour: Int64
        :param minute: Int64
        :param second: Int64
        :return: formatted time string
        >>> timeutils.get_format_time(2001, 7, 18, 1, 1, 1)
        "2001-07-18 01:01:01"
        */
        let dt = DateTime(year, month, day, hour, minute, second)
        dt.format("yyyy-MM-dd HH:mm:ss")
    }
