import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    /*
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    */

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let rad = x * PI / 180.0
        return taylor(x, n: 20)
    }

    public func factorial(a: Int64): Decimal {
        if (a <= 1) {
            return Decimal(1)
        }
        var result = Decimal(1)
        for (i in 2..a+1) {
            result = result * Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let rad = x * PI / 180.0
        var sum = Float64(0)
        for (i in 0..n) {
            let term = Float64(1.0)
            let power = Float64(2 * i)
            let sign = if (i % 2 == 0) { 1.0 } else { -1.0 }
            let numerator = Decimal(pow(rad, power))
            let denominator = factorial(2 * i)
            let decimalTerm = numerator / denominator
            sum = sum + sign * Float64(decimalTerm)
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
        return cos(90.0 - x)
    }

    public func tan(x: Float64): Option<Float64> {
        let cosVal = cos(x)
        if (abs(cosVal - 0.0) <= 0.000001) {
            return None<Float64>
        }
        return Some<Float64>(sin(x) / cosVal)
    }
}

