    */

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        /*
        Calculate the cos value of the x-degree angle
        :param x:Float64
        :return:Float64
        >>> tricalculator = TriCalculator()
        >>> tricalculator.cos(60.0)
        0.5
        */
        let rad = x * PI / 180.0
        return this.taylor(x, 20)
    }

    public func factorial(a: Int64): Decimal {
        /*
        Calculate the factorial of a
        :param a: Int64
        :return: Decimal
        >>> tricalculator.factorial(5)
        Decimal(120)
        */
        if (a <= 1) {
            return Decimal(1)
        }
        var result = Decimal(1)
        for (i in 2..a+1) {
            result = result * Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        /*
        Finding the n-order Taylor expansion value of cos (x/180 * pi)
        :param x: Float64
        :param n: Int64
        :return: Float64
        >>> tricalculator.taylor(60.0, 50)
        0.5000000000000001
        */
        let rad = x * PI / 180.0
        var result = Float64(0.0)
        for (k in 0..n+1:2) {
            let term = Float64(pow(-1, k)) * Float64(pow(rad, 2 * k)) / Float64(this.factorial(Int64(2 * k)))
            result = result + term
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        /*
        Calculate the sin value of the x-degree angle
        :param x: Float64
        :return: Float64
        >>> tricalculator.sin(30.0)
        0.5
        */
        let rad = x * PI / 180.0
        var result = Float64(0.0)
        for (k in 0..20+1:2) {
            let term = Float64(pow(-1, k)) * Float64(pow(rad, 2 * k + 1)) / Float64(this.factorial(Int64(2 * k + 1)))
            result = result + term
        }
        return result
    }

