class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let parts = this.url.split("://")
        if (parts.size > 1) {
            Some(parts[0])
        } else {
            None<String>()
        }
    }

    public func get_host(): Option<String> {
        let scheme = this.get_scheme()
        let remaining = match (scheme) {
            case Some(_) => this.url.split("://")[1]
            case None => this.url
        }
        let host_end = remaining.indexOf("/")
        if (host_end >= 0) {
            Some(remaining.substring(0, host_end))
        } else {
            Some(remaining)
        }
    }

    public func get_path(): Option<String> {
        let scheme = this.get_scheme()
        let remaining = match (scheme) {
            case Some(_) => this.url.split("://")[1]
            case None => this.url
        }
        let path_start = remaining.indexOf("/")
        if (path_start >= 0) {
            Some(remaining.substring(path_start))
        } else {
            Some("/")
        }
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let path = this.get_path()
        let query_params = HashMap<String, String>()
        let path_str = match (path) {
            case None => ""
            case Some(val) => val
        }

        let query_start = path_str.indexOf("?")
        if (query_start < 0) {
            return None<HashMap<String, String>>()
        }

        let fragment_start = path_str.indexOf("#")
        let query_end = if (fragment_start >= 0) { fragment_start } else { path_str.size }
        let query_part = path_str.substring(query_start + 1, query_end)

        let pairs = query_part.split("&")
        for (pair in pairs) {
            let kv = pair.split("=")
            if (kv.size == 2) {
                query_params.add(kv[0], kv[1])
            }
        }

        Some(query_params)
    }

    public func get_fragment(): Option<String> {
        let path = this.get_path()
        let path_str = match (path) {
            case None => ""
            case Some(val) => val
        }

        let fragment_start = path_str.indexOf("#")
        if (fragment_start >= 0) {
            Some(path_str.substring(fragment_start + 1))
        } else {
            None<String>()
        }
    }
}

