            return Some(parts[0])
        }
        return None()
    }

    public func get_host(): Option<String> {
        if (this.url.contains("://")) {
            let parts = this.url.split("://", maxSplit: 1)
            let afterScheme = parts[1]
            let hostEnd = afterScheme.find("/")
            if (hostEnd >= 0) {
                return Some(afterScheme.substr(0, hostEnd))
            }
            return Some(afterScheme)
        }
        return None()
    }

    public func get_path(): Option<String> {
        if (this.url.contains("://")) {
            let parts = this.url.split("://", maxSplit: 1)
            let afterScheme = parts[1]
            let pathStart = afterScheme.find("/")
            if (pathStart >= 0) {
                return Some(afterScheme.substr(pathStart))
            }
            return Some("/")
        }
        return None()
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let pathOpt = this.get_path()
        if (pathOpt.isNone()) {
            return None()
        }
        let path = pathOpt.getOrThrow()
        let queryStart = path.find("?")
        if (queryStart < 0) {
            return None()
        }

        let query = path.substr(queryStart + 1)
        let fragmentPos = query.find("#")
        let queryStr = if (fragmentPos >= 0) {
            query.substr(0, fragmentPos)
        } else {
            query
        }

        let params = HashMap<String, String>()
        let pairs = queryStr.split("&")
        for (pair in pairs) {
            let kv = pair.split("=", maxSplit: 1)
            if (kv.size == 2) {
                params.add(kv[0], kv[1])
            } else if (kv.size == 1) {
                params.add(kv[0], "")
            }
        }
        return Some(params)
    }

    public func get_fragment(): Option<String> {
        let hashPos = this.url.find("#")
        if (hashPos >= 0) {
            return Some(this.url.substr(hashPos + 1))
        }
