import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let dot_product = 0.0
        let norm_a = 0.0
        let norm_b = 0.0

        for (i in 0..vector_1.size) {
            dot_product = dot_product + (vector_1[i] * vector_2[i])
            norm_a = norm_a + (vector_1[i] * vector_1[i])
            norm_b = norm_b + (vector_2[i] * vector_2[i])
        }

        norm_a = sqrt(norm_a)
        norm_b = sqrt(norm_b)

        return dot_product / (norm_a * norm_b)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let results = ArrayList<Float64>()
        for (vector in vectors_all) {
            results.add(VectorUtil.similarity(vector_1, vector))
        }
        return results
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let vec_sum_1 = ArrayList<Float64>(vector_list_1[0])
        let vec_sum_2 = ArrayList<Float64>(vector_list_2[0])

        for (i in 1..vector_list_1.size) {
            for (j in 0..vec_sum_1.size) {
                vec_sum_1[j] = vec_sum_1[j] + vector_list_1[i][j]
            }
        }

        for (i in 1..vector_list_2.size) {
            for (j in 0..vec_sum_2.size) {
                vec_sum_2[j] = vec_sum_2[j] + vector_list_2[i][j]
            }
        }

        return VectorUtil.similarity(vec_sum_1, vec_sum_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for (entry in number_dict) {
            result.add(entry.key, log((total_num + 1) / (entry.value + 1)))
        }
        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let dot_product = 0.0
        let norm_a = 0.0
        let norm_b = 0.0

        for (i in 0..vector_1.size) {
            dot_product += vector_1[i] * vector_2[i]
            norm_a += pow(vector_1[i], 2)
            norm_b += pow(vector_2[i], 2)
        }

        if (norm_a == 0.0 || norm_b == 0.0) {
            return 0.0
        }

        return dot_product / (sqrt(norm_a) * sqrt(norm_b))
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let norm_a = 0.0

        for (i in 0..vector_1.size) {
            norm_a += pow(vector_1[i], 2)
        }
        norm_a = sqrt(norm_a)

        for (vec in vectors_all) {
            let dot_product = 0.0
            let norm_b = 0.0

            for (i in 0..vec.size) {
                dot_product += vector_1[i] * vec[i]
                norm_b += pow(vec[i], 2)
            }

            if (norm_a == 0.0 || norm_b == 0.0) {
                result.add(0.0)
            } else {
                result.add(dot_product / (norm_a * sqrt(norm_b)))
            }
        }

        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let vec1 = ArrayList<Float64>([0.0; vector_list_1[0].size])
        let vec2 = ArrayList<Float64>([0.0; vector_list_2[0].size])

        for (v in vector_list_1) {
            for (i in 0..v.size) {
                vec1[i] += v[i]
            }
        }

        for (v in vector_list_2) {
            for (i in 0..v.size) {
                vec2[i] += v[i]
            }
        }

        return VectorUtil.similarity(vec1, vec2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        let total_float = Float64(total_num)

        for (key in number_dict.keys()) {
            let count = number_dict[key] ?? 0.0
            let weight = log((total_float + 1.0) / (count + 1.0))
            result.add(key, weight)
        }

        return result
    }
}

